/*
 * テキストの本文(第10分冊):中学国語・古文単語・国語の総合単元。
 * 書式は lessons_1.js と同じ。追加フィールド:
 *   pre: まずは前提のおさらい(\n で段落), secs[].key: その節で一番大事なこと,
 *   ex[].hint: 解き始めのヒント, ex[].check: 答えの確かめ方,
 *   faq: [[疑問, 答え]], next: 次に学ぶとよい単元とその理由
 */
window.WPS = window.WPS || {};
WPS.LESSONS = WPS.LESSONS || {};
(function (L) {
  // ===== 漢字・語彙 =====
  L.j_kanji = {
    goal: '漢字の音読み・訓読み、熟語の組み立て、部首、送りがなのきまりが分かり、読み書きのミスを減らせるようになる。',
    intro: '漢字は1字ずつ丸暗記するより、【しくみ】を知ってから覚えるほうがずっと楽です。漢字には中国から来た読み(音読み)と、日本語を当てた読み(訓読み)があり、熟語には組み立ての型があり、字の形には意味を表す部品(部首)があります。しくみが分かると、初めて見る熟語でも読み方や意味の見当がつくようになります。',
    pre: '日本語は、【ひらがな・カタカナ・漢字】の3種類の文字をまぜて書きます。ひらがなとカタカナは音だけを表す文字ですが、漢字は1字で【意味】も表す文字です。たとえば「山」という字は、それだけで「やま」という意味をもっています。\n漢字は、もともと昔の中国で作られた文字です。日本には古い時代に伝わり、日本人はその字を、自分たちの言葉を書くために使うようになりました。このため、1つの漢字に「中国風の読み」と「日本語の読み」の2種類があるのです。\n漢字が2字以上つながって1つの言葉になったものを【熟語】といいます。例:学校、山道、読書。熟語の意味は、ふつう1字ずつの意味を組み合わせると分かります。\n漢字の右や上下につけて、言葉の形を表すひらがなを【送りがな】といいます。例:「書く」の「く」、「美しい」の「しい」。\nこの単元では、この4つ(読み方・熟語・部首・送りがな)を順番に見ていきます。',
    secs: [
      { h: '音読みと訓読み', t: 'なぜ1つの漢字に読み方がいくつもあるのでしょうか。それは、漢字が中国から伝わったとき、①中国での発音をまねた読み方と、②同じ意味の日本語を当てた読み方の、両方が使われるようになったからです。\n【音読み】…中国から伝わった発音をもとにした読み方です。それだけ聞いても意味が分かりにくいことが多いです。例:山(サン)、水(スイ)、生(セイ・ショウ)\n【訓読み】…漢字に、同じ意味の日本語を当てた読み方です。聞いただけで意味が分かります。例:山(やま)、水(みず)、生(いきる・うまれる・なま)\n見分けのコツは、【読みだけを聞いて意味が分かるかどうか】です。「やま」と聞けば山だと分かるので訓読み、「サン」と聞いただけでは何のことか分かりにくいので音読みです。\nただし例外もあります。「絵(エ)」「本(ホン)」のように、音読みでも日常語になっていて意味が分かるものがあります。迷ったら辞書で確かめましょう。\n音読みが2つ以上ある字もあります。「生」のセイ・ショウ、「行」のコウ・ギョウ・アンのように、伝わった時代がちがう読みが残っているためです。',
        key: '聞いて意味が分かる読み=訓読み、聞いても意味が分かりにくい読み=音読み。' },
      { h: '熟語の読み方:重箱読み・湯桶読み・熟字訓', t: '熟語はふつう、「音+音」(山脈=サンミャク)か「訓+訓」(山道=やまみち)で読みます。上と下で読み方の種類がそろうのが基本です。\nところが、上と下で種類が混ざる熟語もあります。それぞれに名前がついています。\n【重箱読み】…上が音、下が訓。「重箱」自体が、ジュウ(音)+ばこ(訓)と読むので、この名前がつきました。例:台所(ダイ+どころ)、本棚(ホン+だな)、番組(バン+ぐみ)\n【湯桶読み】…上が訓、下が音。「湯桶」が、ゆ(訓)+トウ(音)と読むことから。例:手帳(て+チョウ)、身分(み+ブン)、荷物(に+モツ)\n覚え方:名前の熟語そのものが、その読み方の見本になっています。「重箱=音訓」「湯桶=訓音」と、名前で確かめれば迷いません。\nもう1つ、【熟字訓】という読み方があります。熟語全体に、まとめて1つの訓読みを当てるものです。1字ずつに分けて読むことはできません。例:明日(あす)、今日(きょう)、大人(おとな)、七夕(たなばた)、時計(とけい)',
        key: '重箱読み=上が音・下が訓、湯桶読み=上が訓・下が音。名前の熟語そのものが見本になっている。',
        ex: [{ q: '「台所」「手帳」は、それぞれ重箱読み・湯桶読みのどちら?', hint: 'まず1字ずつ、音読みか訓読みかを決めよう。', steps: ['台所を1字ずつ見る:「台」はダイ(聞いても意味が分かりにくい → 音)、「所」はどころ(ところ=場所と分かる → 訓)。', '上が音・下が訓。これは「重箱(ジュウ+ばこ)」と同じ型なので、重箱読み。', '手帳を1字ずつ見る:「手」はて(意味が分かる → 訓)、「帳」はチョウ(音)。', '上が訓・下が音。これは「湯桶(ゆ+トウ)」と同じ型なので、湯桶読み。'], a: '台所=重箱読み、手帳=湯桶読み', check: '「重箱」「湯桶」それぞれの読み方(ジュウ+ばこ、ゆ+トウ)と、上下の種類の並びが同じかを見比べる。' }] },
      { h: '二字熟語の組み立て(5つの型)', t: '二字熟語は、2つの漢字がどんな関係で結びついているかによって、いくつかの型に分けられます。型が分かると、知らない熟語でも意味の見当がつきます。\n①【似た意味を重ねる】例:岩石(岩も石も同じ仲間)、増加、豊富\n②【反対・対の意味を重ねる】例:高低、左右、売買\n③【上が下をくわしくする(修飾)】例:青空(青い空)、急増(急に増える)、親友(親しい友)\n④【下が上の目的・対象になる】例:読書(書を読む)、登山(山に登る)、乗車(車に乗る)\n⑤【上が主語、下が述語】例:日没(日が没する)、国立(国が立てる)、地震(地が震える)\nこのほか、上に【不・無・非・未】がついて打ち消す型もあります。例:不安(安らかでない)、無理、非常、未定(まだ定まっていない)\n見分けるコツは、熟語を【訓読みして短い文にしてみる】ことです。「〜を」「〜に」を補うと自然な文になれば④、「〜が」を補うと自然になれば⑤です。③は「〜い」「〜な」「〜に」などで上が下をくわしくしています。',
        key: '熟語を訓読みして短い文にしてみる。「を・に」が入れば④、「が」が入れば⑤。',
        ex: [{ q: '「登山」「日没」「豊富」の組み立てを答えよう。', hint: '1字ずつ訓読みして、短い文にしてみよう。', steps: ['登山:訓読みして文にする →「山に登る」。「〜に」が入り、下の「山」が「登る」の対象になっている → ④(下が上の目的・対象)。', '日没:「日が没する(しずむ)」。「〜が」が入り、上が主語・下が述語 → ⑤。', '豊富:「豊か」「富む」は、どちらも「たくさんある」という似た意味 → ①(似た意味を重ねる)。'], a: '登山=下が上の目的・対象、日没=上が主語・下が述語、豊富=似た意味を重ねる', check: '同じ型の熟語(登山なら読書・乗車)を思いうかべ、同じように文にできるか確かめる。' }] },
      { h: '部首:漢字の「部品」で意味を知る', t: '多くの漢字は、いくつかの部品が組み合わさってできています。その中で、漢字を分類するときの目印になる部品を【部首】といいます。部首は、その漢字の【意味のグループ】を表していることが多いです。\n部首は、字のどこにあるかで7つの種類に分けられます。\n【へん】(左):にんべん(休・体)…人に関係、さんずい(海・池)…水に関係\n【つくり】(右):おおざと(都・部)、ちから(助・動)\n【かんむり】(上):くさかんむり(花・草)…植物に関係、うかんむり(家・室)…家・屋根に関係\n【あし】(下):れっか/れんが(点・熱)…火に関係、こころ(思・悲)…心に関係\n【たれ】(上から左へ):まだれ(広・庫)、やまいだれ(病・痛)…病気に関係\n【にょう】(左から下へ):しんにょう/しんにゅう(道・近)…道や進むことに関係\n【かまえ】(外側を囲む):もんがまえ(間・開)、くにがまえ(国・園)\n部首の意味を知っていると、たとえば「さんずいだから水に関係がある字だな」と、字の意味や書き分けの手がかりになります。',
        key: '部首は漢字の意味のグループを表す。へん・つくり・かんむり・あし・たれ・にょう・かまえの7種類。',
        ex: [{ q: '「海」「花」「道」の部首の名前と、その部首が表す意味を答えよう。', hint: '字のどの位置に共通の部品があるかを見よう。', steps: ['「海」は左側に「氵」がある。左側の部首は「へん」で、名前は「さんずい」。水に関係する字につく(池・波・泳 なども同じ)。', '「花」は上に「艹」がある。上の部首は「かんむり」で、名前は「くさかんむり」。植物に関係する(草・茶・葉)。', '「道」は左から下へ「辶」がある。この形は「にょう」で、名前は「しんにょう(しんにゅう)」。道や進むことに関係する(近・通・進)。'], a: '海=さんずい(水)、花=くさかんむり(植物)、道=しんにょう(道・進む)', check: '同じ部首をもつほかの字を思いうかべ、意味の共通点があるかを確かめる。' }] },
      { h: '送りがなのきまり', t: 'なぜ送りがなが必要なのでしょうか。たとえば「書」だけでは、「書く」なのか「書いた」なのか「書けば」なのか分かりません。言葉の形が変わる部分をひらがなで書きそえることで、正しく読めるようにしているのです。\nそこで、送りがなは【形が変わる部分(活用語尾)を送る】のが基本です。\n例:書く(書か・書き・書け…と「く」の部分が変わる)、話す、高い(高く・高かった)、静かだ(静かな・静かに)\nよく出る決まり:\n・「〜しい」で終わる形容詞は「し」から送る。例:美しい、新しい、正しい\n・「か・やか・らか」をふくむ形容動詞は、その部分から送る。例:静かだ、穏やかだ、明らかだ\n・ほかの語をふくむ語は、もとの語の送りがなに合わせる。例:動かす(「動く」をふくむので「動す」としない)、浮かぶ(「浮く」をふくむ)\n・例外もある。例:少ない、危ない、大きい、小さい(活用語尾より前から送る)\n迷ったら、その語を「ない・ます・ば」などにつなげて形を変えてみて、【変わらない部分=漢字、変わる部分=送りがな】と考えます。',
        key: '送りがなは、形が変わる部分(活用語尾)を送るのが基本。形を変えてみて確かめる。',
        ex: [{ q: '「うごかす」「みじかい」を、漢字と送りがなで正しく書こう。', hint: '形を変えてみて、変わる部分を探そう。もとになる語があるかも考えよう。', steps: ['「うごかす」は「うごかさない・うごかします・うごかせば」と変わり、変わるのは「す」の部分。', 'ただし「うごかす」は「動く」という語をふくんでいる。もとの「動く」の送りがな(く→か に対応)に合わせて「か」から送る → 動かす。', '「みじかい」は「みじかく・みじかかった」と変わり、変わるのは「い」の部分。', '形容詞の基本どおり「い」だけを送る → 短い(「短かい」は誤り)。'], a: '動かす/短い', check: '「動かない(動く)」「短く」のように形を変えて、漢字の部分が変わらないことを確かめる。' }] },
      { h: '同音異義語・同訓異字は「意味」で選ぶ', t: '読みが同じで意味がちがう漢字の書き分けは、ミスがいちばん多いところです。なぜまちがえるかというと、読みだけで覚えていて、【意味】と結びつけていないからです。\n【同音異義語】(音読みが同じ熟語)\n・意外(思いがけない)/以外(それをのぞくほか)\n・関心(興味をもつ)/感心(りっぱだと思う)\n・対象(目標・相手になるもの)/対称(つり合っている。左右対称)/対照(比べ合わせる。対照的)\n【同訓異字】(訓読みが同じ漢字)\n・会う(人と)/合う(一致する)/遭う(事故などに)\n・計る(時間)/測る(長さ・深さ)/量る(重さ・量)/図る(計画する。解決を図る)\n・治める(国を)/収める(成果を)/納める(税を)/修める(学問を)\n書き分けるときは、その漢字を使った【別の熟語】を思い出すと確実です。例:「測る」→ 測量、「量る」→ 重量、「納める」→ 納税、「修める」→ 修学。',
        key: '同じ読みの字は、その字を使った別の熟語を思い出して、意味で選ぶ。',
        ex: [{ q: '「体重をハカる」「川の深さをハカる」の「ハカる」を漢字にしよう。', hint: '何をはかっているのか(重さ? 長さ?)を考えよう。', steps: ['体重は「重さ」。重さ・量をはかるのは「量る」(重量・分量の「量」)。', '深さは「長さ・深さ」のなかま。長さ・深さ・広さをはかるのは「測る」(測量・測定の「測」)。', '時間なら「計る」(計時)なので、ここでは使わない。'], a: '体重を量る/川の深さを測る', check: '「重量」「測量」という熟語に置きかえて、意味が通るか確かめる。' },
          { q: '「左右タイショウの図形」「中学生をタイショウにした本」の「タイショウ」を漢字にしよう。', hint: 'タイショウには「対象・対称・対照」がある。それぞれの意味を思い出そう。', steps: ['「左右タイショウ」は、左右がつり合っていること → つり合いを表す「対称」。', '「中学生をタイショウにした」は、本の相手・目標が中学生ということ → 目標・相手を表す「対象」。', '「対照」は「比べ合わせる」意味(対照的な性格)なので、どちらにも合わない。'], a: '左右対称の図形/中学生を対象にした本', check: '「対称=つり合い」「対象=相手」と意味を当てはめて、文が自然になるか読み直す。' }] }
    ],
    faq: [['音読みと訓読みは、どうして見分けにくいことがあるの?', '長い間使われているうちに、音読みの言葉が日常語になったものがあるからです。「絵(エ)」「本(ホン)」「菊(キク)」は音読みですが、聞いただけで意味が分かります。\n迷ったときは、「その字の訓読みが別にあるか」を考えると手がかりになります。それでも分からなければ辞書で確かめましょう。'], ['部首は、なぜ覚える必要があるの?', '部首はその字の意味のグループを表すので、意味の見当をつけたり、同訓異字を書き分けたりする手がかりになるからです。\nまた、漢和辞典(漢字の辞書)は部首ごとに字が並んでいるので、読めない字を調べるときにも役立ちます。'], ['送りがなに例外があるのはなぜ?', '送りがなは、読みまちがいを防ぐために決められたきまりです。たとえば「少い」だと「すくない」とも「すこし」とも読めて紛らわしいので、「少ない」と送ることになっています。\n例外はそれほど多くないので、よく出るもの(少ない・危ない・大きい・小さい など)だけ覚えておけば十分です。']],
    terms: [['音読み', '中国から伝わった発音をもとにした読み方'], ['訓読み', '漢字に同じ意味の日本語を当てた読み方'], ['重箱読み', '熟語の上を音、下を訓で読む読み方'], ['湯桶読み', '熟語の上を訓、下を音で読む読み方'], ['熟字訓', '熟語全体に1つの訓読みを当てる読み方(明日=あす など)'], ['部首', '漢字を分類する目印になる部品。意味のグループを表すことが多い'], ['活用語尾', '語の形が変わる部分。送りがなの基本になる'], ['同音異義語', '読みが同じで意味がちがう熟語']],
    miss: ['読めるだけで安心して、書く練習をしない。読める漢字と書ける漢字は別なので、手で書いて覚える。', '送りがなを1字多く・少なく書く(「短かい」「少い」など)。形を変えてみて、変わる部分だけを送っているか確かめる。', '同音異義語を、意味を考えずに見なれた方で書いてしまう。書く前に、その字を使った別の熟語を1つ思い出すくせをつける。', '重箱読みと湯桶読みを逆に覚える。「重箱=ジュウ(音)ばこ(訓)」と、名前の熟語で毎回確かめる。'],
    sum: ['聞いて意味が分かる読み=訓読み、分からない読み=音読み。', '上が音・下が訓=重箱読み、上が訓・下が音=湯桶読み。熟語全体に訓を当てる=熟字訓。', '熟語の組み立ては、訓読みして文にすると見分けられる。', '部首は意味のグループを表す。へん・つくり・かんむり・あし・たれ・にょう・かまえ。', '送りがなは形が変わる部分を送るのが基本。もとの語をふくむ語はそれに合わせる。', '同音・同訓の字は、ほかの熟語を思い出して意味で選ぶ。'],
    next: '次は「語彙・ことわざ」に進みましょう。漢字1字ずつの意味が分かっていると、四字熟語や故事成語の意味もぐっと覚えやすくなります。'
  };

  L.j_m1 = {
    goal: '意味を取りちがえやすい言葉・ことわざ・慣用句・四字熟語・故事成語の正しい意味が分かり、文章の中で正しく使えるようになる。',
    intro: '言葉の意味をなんとなくで覚えていると、文章を読んだときに意味が逆になってしまうことがあります。たとえば「おもむろに」を「突然に」だと思っていると、場面のようすがまったくちがって見えます。この単元では、【まちがえやすい言葉】と、昔から使われてきた【ことわざ・慣用句・四字熟語・故事成語】を、意味ごと正しく覚えます。',
    pre: '言葉には、文字どおりの意味と、たとえとしての意味があります。たとえば「頭をかかえる」は、本当に頭を手でかかえることもありますが、ふつうは「どうしたらよいか困る」という意味で使います。\nこの単元で学ぶ言葉の多くは、こうした【たとえとしての意味】をもつ言葉です。文字どおりに読むと、意味をまちがえてしまいます。\nまた、言葉の意味は時代とともに変わることがあります。多くの人が本来とちがう意味で使っている言葉もあり、テストではそこがよく問われます。\n意味を調べるときは【国語辞典】を使います。国語辞典には、本来の意味に加えて「誤って〜の意味で使われることがある」と書いてあることも多いので、ぜひ確かめるくせをつけましょう。',
    secs: [
      { h: '意味を取りちがえやすい言葉', t: 'なぜ意味を取りちがえるのでしょうか。多くの場合、【言葉の見た目や音から、意味を想像してしまう】からです。「役不足」は「役に対して不足している」と読めてしまうので、「力が足りない」とまちがえやすいのです。\n【おもむろに】…ゆっくりと、落ち着いて。(×突然に)\n【役不足】…その人の力量に比べて、役目が軽すぎること。(×役目に対して力が足りない。それは「力不足」)\n【気が置けない】…遠慮しなくてよい、気楽につきあえる。(×油断できない)\n【情けは人のためならず】…人に親切にすると、めぐりめぐって自分によい報いがある。(×親切はその人のためにならない)\n【失笑】…こらえきれずに思わず笑ってしまうこと。(×笑いも出ないほどあきれる)\n【すべからく】…当然、ぜひとも(「すべからく〜べし」の形で)。(×すべて)\n覚えるときは、【まちがった意味とセットで】覚えると、選択肢でひっかからなくなります。',
        key: 'まちがえやすい言葉は、正しい意味と、よくある誤った意味をセットで覚える。',
        ex: [{ q: '「彼は気が置けない友人だ」の意味は?', hint: '「気が置けない」は「油断できない」ではない。', steps: ['「気が置けない」=気をつかう必要がない、遠慮がいらない、という意味。', '「油断できない」は誤った意味なので注意する。「友人」という言葉ともよく合う。', '文全体に当てはめて言いかえる。'], a: '彼は、遠慮せずに気楽につきあえる友人だ。', check: '「油断できない友人だ」と読むと、親しい友人をほめる文の調子と合わないことを確かめる。' },
          { q: '次のうち「役不足」の使い方が正しいものはどれ?\nア 新人の私には、この大役は役不足です。\nイ 優勝経験のある彼に、補欠の役は役不足だ。', hint: '役不足は「役目が軽すぎる」という意味。', steps: ['「役不足」は、その人の力に比べて役目が軽すぎる、という意味。', 'ア:新人が「大役」を引き受ける場面。言いたいのは「自分の力が足りない」こと → それは「力不足」。アは誤り。', 'イ:優勝経験のある実力者に補欠の役 → 役目が軽すぎる → 正しい。'], a: 'イ', check: 'アを「力不足です」に直すと意味が通ることも確かめる。' }] },
      { h: 'ことわざは「似た意味」「反対の意味」で整理', t: '【ことわざ】は、昔からの知恵や教えを、短く覚えやすい形で言い表した言葉です。人々の生活の中で生まれたので、動物や身近な道具がよく出てきます。\nばらばらに覚えるより、グループで覚えると効率的です。\n似た意味:\n・【猿も木から落ちる】【弘法にも筆の誤り】【かっぱの川流れ】…名人でも失敗することがある。\n・【ぬかに釘】【のれんに腕押し】【豆腐にかすがい】…手ごたえや効き目がない。\n・【二階から目薬】…思うようにならず、もどかしい。\n反対の意味:\n・【急がば回れ】(急ぐときほど安全な道を選べ)⇔【善は急げ】(よいことはすぐにせよ)\n・【蛙の子は蛙】(子は親に似る)⇔【とびがたかを生む】(平凡な親からすぐれた子が生まれる)\nことわざの意味を考えるときは、【出てくるものの特ちょう】に注目します。「猿=木登りの名人」「かっぱ=泳ぎの名人」と分かれば、「名人でも失敗する」という意味が見えてきます。',
        key: 'ことわざは、似た意味・反対の意味のグループで覚える。出てくるものの特ちょうから意味を考える。',
        ex: [{ q: '「弘法にも筆の誤り」と似た意味のことわざを1つ答えよう。', hint: '弘法大師は書の名人。「名人が失敗する」話を探そう。', steps: ['まず意味を確認:書の名人の弘法大師でも書きまちがえる → 名人でも失敗することがある。', '同じ「名人も失敗する」という意味のものを探す。', '木登りの名人の猿が木から落ちる(猿も木から落ちる)、泳ぎの名人のかっぱが流される(かっぱの川流れ)。'], a: '猿も木から落ちる(かっぱの川流れ でもよい)', check: 'どちらも「その道の名人」+「失敗」の組み合わせになっているかを確かめる。' }] },
      { h: '慣用句は体の部分で覚える', t: '【慣用句】は、2つ以上の言葉が結びついて、もとの言葉とはちがう特別な意味を表す、決まった言い方です。ことわざとのちがいは、ことわざが「教え・知恵」をふくむ1つの文のようなものなのに対し、慣用句は文の一部として使う【言い回し】だという点です。\n体の部分を使ったものが多くあります。\n【舌を巻く】…すばらしさに、ひどく感心する。\n【耳が痛い】…自分の弱点を言われて、聞くのがつらい。\n【腹を割る】…本心を打ち明ける。\n【肩を持つ】…味方をする、ひいきする。\n【顔が広い】…知り合いが多い。\n【手を焼く】…あつかいに困る、てこずる。\n【目を見張る】…驚いたり感心したりして、目を大きく開く。\n文字どおりの意味(本当に舌を巻く)ではないことに注意します。意味を考えるときは、その体の部分が【どんな気持ちや動作と関係するか】をイメージすると覚えやすくなります。',
        key: '慣用句は文字どおりではなく、決まった特別な意味をもつ。体の部分ごとにまとめて覚える。',
        ex: [{ q: '「母はいつも弟の(  )を持つので、きょうだいげんかになると私が負ける。」(  )に入る体の部分を答えよう。', hint: '「味方をする」という意味の慣用句を思い出そう。', steps: ['文の意味を考える:けんかで私が負けるのは、母が弟の味方をするから。', '「味方をする・ひいきする」という意味の慣用句は「肩を持つ」。', '( )に「肩」を入れて読み、意味が通るか確かめる。'], a: '肩', check: '「母はいつも弟の味方をする」と言いかえて、「私が負ける」という結果と自然につながるか確かめる。' }] },
      { h: '四字熟語は漢字の意味から考える', t: '【四字熟語】は、4つの漢字で1つのまとまった意味を表す言葉です。多くは「2字+2字」に分けられるので、漢字の意味を分解すると覚えやすくなります。\n【異口同音】…異なる口から同じ音 → 多くの人が口をそろえて同じことを言う。\n【一石二鳥】…1つの石で2羽の鳥 → 1つのことで2つの得をする。\n【半信半疑】…半分信じて半分疑う → 本当かどうか迷う。\n【自業自得】…自分の行い(業)の結果を自分が受ける。\n【以心伝心】…心をもって心に伝える → 言葉にしなくても気持ちが通じ合う。\n【一朝一夕】…ひと朝やひと晩 → ごく短い期間(「一朝一夕にはできない」の形が多い)。\n書くときは、似た字に注意します。「異口同音」を「異句同音」としないのは、「口」で言うからです。漢字の意味で理由をつけると、書きまちがいも防げます。',
        key: '四字熟語は「2字+2字」に分け、漢字1字ずつの意味から全体の意味を組み立てる。',
        ex: [{ q: '「イクドウオン」を漢字で書き、意味を答えよう。', hint: '「異なる口」「同じ音(声)」と分けて考えよう。', steps: ['「イク」は「異なる口」→ 異口。言葉は口から出るので「口」(句ではない)。', '「ドウオン」は「同じ音(声)」→ 同音。', '合わせて「異口同音」。たくさんの口から同じ声が出る → 多くの人が同じことを言う。'], a: '異口同音/多くの人が口をそろえて同じことを言うこと', check: '「クラス全員が異口同音に賛成した」のように文に入れて、意味が自然か確かめる。' }] },
      { h: '故事成語は「もとの話」とセットで', t: '【故事成語】は、中国の昔の出来事や物語(故事)からできた言葉です。もとの話を知らないと、字だけ見ても意味が分かりません。逆に、話を知っていれば、意味は自然に覚えられます。\n【矛盾】…どんな盾も突き通す矛と、どんな矛も防ぐ盾を売る人が、「その矛でその盾を突いたらどうなるか」と問われて答えられなかった話から。つじつまが合わないこと。\n【蛇足】…蛇の絵をかく競争で、早くかき終えた人が、よけいな足までかき足して負けた話から。よけいなつけ足し。\n【五十歩百歩】…戦場で五十歩逃げた兵士が、百歩逃げた兵士を笑った話から。少しのちがいはあっても、本質は同じこと。\n【漁夫の利】…しぎとはまぐりが争っている間に、漁師が両方を捕まえた話から。二者が争う間に、第三者が利益を得ること。\n【杞憂】…杞の国の人が、天が落ちてこないかと心配して、夜も眠れなかった話から。必要のない心配、取りこし苦労。\n【推敲】…唐の詩人 賈島が、詩の一句を「推す」にするか「敲く」にするか迷った話から。文章を何度も練り直すこと。',
        key: '故事成語は、もとの話の筋と意味をいっしょに覚える。',
        ex: [{ q: '「明日の試験が難しすぎたらどうしようと心配していたが、杞憂に終わった。」の「杞憂」の意味は?', hint: '杞の国の人は、何を心配していたのだろう。', steps: ['もとの話:杞の国の人が「天が落ちてくるのでは」と心配した。', '天が落ちてくることは、まずない → する必要のない心配。', '文に当てはめる:心配していたことは起こらず、取りこし苦労だった。'], a: '必要のない心配(取りこし苦労)', check: '「杞憂に終わった」を「心配する必要がなかった」と言いかえて、文の意味が通るか確かめる。' }] }
    ],
    faq: [['ことわざと慣用句は、どうちがうの?', 'ことわざは、生活の知恵や教えをふくんだ、それだけで1つの文のようなまとまりです(例:急がば回れ)。\n慣用句は、文の一部として使う決まった言い回しで、教えはふくみません(例:「顔が広い」→「彼は顔が広い」)。'], ['まちがった意味で使う人が多いなら、そちらが正しくなるのでは?', '言葉の意味は時代とともに変わることがあり、辞書に新しい意味が加わることもあります。\nただし、テストや改まった文章では、本来の意味が基準になります。また、相手がどちらの意味で受け取るか分からないと誤解が生まれるので、本来の意味を知っておくことが大切です。'], ['たくさんあって覚えきれません。どうすればいい?', '1日にたくさん覚えるより、グループ(似た意味・反対の意味・体の部分など)ごとに少しずつ覚えるのが効果的です。\n覚えた言葉を、自分で短い文に入れて使ってみると、意味が記憶に残りやすくなります。']],
    terms: [['ことわざ', '昔からの知恵や教えを、短く言い表した言葉'], ['慣用句', '2語以上が結びついて、特別な意味を表す決まった言い方'], ['四字熟語', '4つの漢字で1つのまとまった意味を表す熟語'], ['故事成語', '中国の昔の出来事や物語からできた言葉(矛盾・推敲など)'], ['役不足', '力量に比べて役目が軽すぎること'], ['杞憂', '必要のない心配。取りこし苦労']],
    miss: ['「役不足」を「力が足りない」の意味で使ってしまう。見た目から意味を想像したのが原因なので、「力不足」とセットで覚える。', '「情けは人のためならず」を「親切は相手のためにならない」と読んでしまう。「ならず」は「〜ではない」の意味で、「人のためではない(自分のためだ)」と読む。', '慣用句を文字どおりの意味で考えてしまう。慣用句は特別な意味をもつ決まった言い方だと意識する。', '四字熟語の字を音だけで書き、「異句同音」「一石二丁」などとまちがえる。1字ずつの意味で理由をつけて書く。'],
    sum: ['まちがえやすい言葉は、誤った意味とセットで覚える。', 'ことわざは「似た意味」「反対の意味」のグループで整理する。', '慣用句は文字どおりではない。体の部分ごとにまとめると覚えやすい。', '四字熟語は、漢字1字ずつの意味から考える。', '故事成語は、もとの話とセットで覚える。'],
    next: '次は「文法・敬語」の単元で、文を単語に分けて品詞を見分ける練習をしましょう。言葉の意味に加えて、言葉の働きが分かると、文章を正確に読めるようになります。'
  };

  // ===== 文法 =====
  var HINSHI = '<svg viewBox="0 0 300 196" class="lz-fig" role="img" aria-label="10品詞の分類図。単語を自立語と付属語に分け、活用するかどうか、どんな働きをするかで10品詞に分ける"><line x1="30" y1="119" x2="48" y2="67" class="ax"/><line x1="30" y1="119" x2="48" y2="171" class="ax"/><line x1="86" y1="67" x2="104" y2="32" class="ax"/><line x1="86" y1="67" x2="104" y2="102" class="ax"/><line x1="86" y1="171" x2="104" y2="160" class="ax"/><line x1="86" y1="171" x2="104" y2="182" class="ax"/><line x1="160" y1="32" x2="180" y2="16" class="ax"/><line x1="160" y1="32" x2="180" y2="32" class="ax"/><line x1="160" y1="32" x2="180" y2="48" class="ax"/><line x1="164" y1="102" x2="180" y2="70" class="ax"/><line x1="164" y1="102" x2="180" y2="86" class="ax"/><line x1="164" y1="102" x2="180" y2="102" class="ax"/><line x1="164" y1="102" x2="180" y2="118" class="ax"/><line x1="164" y1="102" x2="180" y2="134" class="ax"/><line x1="160" y1="160" x2="180" y2="160" class="ax"/><line x1="164" y1="182" x2="180" y2="182" class="ax"/><text x="4" y="123">単語</text><text x="50" y="71">自立語</text><text x="50" y="175">付属語</text><text x="106" y="36">活用する</text><text x="106" y="106">活用しない</text><text x="106" y="164">活用する</text><text x="106" y="186">活用しない</text><text x="183" y="20">動詞(ウ段)</text><text x="183" y="36">形容詞(い)</text><text x="183" y="52">形容動詞(だ)</text><text x="183" y="74">名詞(主語になる)</text><text x="183" y="90">副詞(用言を修飾)</text><text x="183" y="106">連体詞(体言を修飾)</text><text x="183" y="122">接続詞(つなぐ)</text><text x="183" y="138">感動詞(独立)</text><text x="183" y="164">助動詞</text><text x="183" y="186">助詞</text></svg>';
  L.j_m2 = {
    goal: '文を文節と単語に分け、文節どうしの関係をつかみ、決まった手順で10品詞のどれかを見分けられるようになる。',
    intro: '品詞分けは、カンで決めるものではありません。単語に対して【3つの質問】を順番にするだけで、だれでも同じ答えにたどりつけます。①1語で意味が分かる言葉か(自立語か付属語か)、②形が変わるか(活用するか)、③文の中でどんな働きをするか。この順番どおりに進む、迷路のようなものだと考えてください。',
    pre: '【文】とは、ひとまとまりの内容を表し、ふつう「。」で終わる言葉の連なりです。例:「花がさいた。」\n文の中で「何が(だれが)」に当たる部分を【主語】、「どうする・どんなだ・何だ」に当たる部分を【述語】といいます。「花がさいた」なら、主語は「花が」、述語は「さいた」です。\n言葉には、名前を表す言葉(花・学校)、動きを表す言葉(さく・走る)、ようすを表す言葉(美しい・静かだ)など、いろいろな種類があります。この種類のことを【品詞】といいます。\n小学校で習った「名詞」「動詞」なども品詞の名前です。中学では、これを10種類に整理して、見分け方の手順を学びます。\n品詞を見分ける前に、まず文を小さな単位に区切る練習をします。区切り方には「文節」と「単語」の2段階があります。',
    secs: [
      { h: '準備1:文節と単語に区切る', t: '品詞は「単語」ごとに決めるものです。でも、いきなり単語に分けるのは難しいので、まず少し大きな単位の「文節」に区切ります。\n【文節】…文を、発音や意味が不自然にならない範囲で、できるだけ短く区切ったまとまりです。間に「ネ」や「サ」を入れて自然に読めるところが区切りです。\n例:「美しい花が さいた。」→ 美しい(ネ)/花が(ネ)/さいた(ネ)。→ 3文節。\n【単語】…文節をさらに、意味をもつ最小の単位まで分けたものです。\n例:美しい/花/が/さい/た → 5単語。\n1つの文節には、必ず1つの【自立語】が、文節の先頭にあります。そのあとに【付属語】(が・た など)がつくことがあります。だから、文節の先頭の語を見つければ、自立語が分かります。',
        key: '文節は「ネ」を入れて区切る。文節の先頭には必ず自立語が1つある。',
        ex: [{ q: '「私は毎朝公園を走る。」を文節に区切り、文節の数を答えよう。', hint: '「ネ」を入れて自然に読めるところで区切ろう。', steps: ['「ネ」を入れて読んでみる:私は(ネ)毎朝(ネ)公園を(ネ)走る。', '「私ネは」「公園ネを」のように、「は」「を」の前で区切ると不自然になる。「は・を」は前の語にくっつく付属語だから。', '区切りは「私は/毎朝/公園を/走る」。'], a: '私は/毎朝/公園を/走る(4文節)', check: '各文節の先頭に自立語(私・毎朝・公園・走る)が1つずつあるかを確かめる。' }] },
      { h: '準備2:文節どうしの関係', t: '文節は、ばらばらに並んでいるのではなく、たがいに関係し合って文を作っています。おもな関係は次の6つです。\n【主語・述語の関係】…「何が」と「どうする・どんなだ」。例:花が/さいた\n【修飾・被修飾の関係】…くわしくする文節(修飾語)と、くわしくされる文節(被修飾語)。例:美しい→花が、ゆっくり→歩く\n【接続の関係】…前後をつなぐ。例:雨が降ったので/中止だ\n【独立の関係】…ほかの文節と直接関係しない。例:はい、/そうです\n【並立の関係】…対等に並ぶ。例:赤い/白い/花\n【補助の関係】…下の文節が上に意味をそえる。例:書いて/いる\n修飾語がどの文節にかかるかは、【2つの文節をつなげて読み、意味が通るか】で確かめます。',
        key: '修飾語のかかり先は、2つの文節だけをつなげて読み、意味が通るかで確かめる。',
        ex: [{ q: '「小さな 鳥が 空を 高く 飛ぶ。」で、「高く」はどの文節をくわしくしている?', hint: '「高く」とほかの文節を1つずつつなげて読んでみよう。', steps: ['「高く鳥が」→ 意味が通らない。', '「高く空を」→ これだけでは意味がまとまらない(「空を」も、あとの「飛ぶ」にかかる文節)。', '「高く飛ぶ」→ 自然に意味が通る。どのように飛ぶかをくわしくしている。'], a: '飛ぶ', check: '「高く」を取りのぞいて「小さな鳥が空を飛ぶ」としても文が成り立ち、「飛ぶ」のようすが減るだけであることを確かめる。' }] },
      { h: '自立語・付属語と「活用」', t: '品詞を見分けるための、2つの大事な考え方を説明します。\n【自立語】…それだけで意味が分かり、1つで文節を作れる単語。例:花、さく、美しい、とても\n【付属語】…それだけでは意味がはっきりせず、いつも自立語のあとについて使われる単語。例:が、を、は、た、ない\n次に【活用】です。活用とは、後ろにつく言葉によって、語の形が変わることです。\n例:「書く」→ 書かない/書きます/書く/書くとき/書けば/書こう\nこのように形が変わる語を「活用する語」といいます。「花」は「花が・花を」となっても「花」の部分は変わらないので、活用しません。\n活用するかどうかは、後ろに【「ない」「ます」「とき」「ば」】などをつけて、形が変わるかどうかで確かめます。',
        key: '活用=後ろにつく言葉によって形が変わること。「ない・ます・とき・ば」をつけて確かめる。' },
      { h: '品詞を見分ける手順', t: '単語ごとに、次の手順で調べます。図の左から右へ進むイメージです。\n【手順1】自立語か、付属語か。\n【手順2】活用する(形が変わる)か。\n・付属語で活用する → 【助動詞】(た・ない・れる・ようだ など)。活用しない → 【助詞】(が・を・は・から など)。\n【手順3】自立語で活用するもの(用言)は、【言い切りの形(終止形)】で決める。\n・ウ段の音で終わる → 【動詞】(書く・見る・する)\n・「い」で終わる → 【形容詞】(高い・美しい)\n・「だ・です」で終わる → 【形容動詞】(静かだ・きれいだ)\n【手順4】自立語で活用しないものは、働きで決める。\n・主語になれる(「が」をつけられる)→ 【名詞】\n・主に用言(動詞・形容詞・形容動詞)をくわしくする → 【副詞】(ゆっくり・とても)\n・体言(名詞)だけをくわしくする → 【連体詞】(この・その・ある・大きな)\n・文と文、語と語をつなぐ → 【接続詞】(しかし・だから)\n・ほかと関係せず独立している(呼びかけ・応答・感動)→ 【感動詞】(ああ・はい・おい)', fig: HINSHI,
        key: '「自立語か付属語か → 活用するか → 言い切りの形・働き」の順に質問すれば、品詞は必ず1つに決まる。',
        ex: [{ q: '「美しい花がさいた。」を単語に分け、それぞれの品詞を答えよう。', hint: 'まず文節に区切り、文節の先頭の語(自立語)を見つけよう。', steps: ['文節に区切る:美しい/花が/さいた。さらに単語に分ける:美しい/花/が/さい/た。', '文節の先頭にある「美しい」「花」「さい」が自立語。残りの「が」「た」が付属語。', '付属語:「が」は形が変わらない → 助詞。「た」は「たろう・たら」と変わる → 助動詞。', '自立語で活用するもの:「美しい」は言い切りが「い」→ 形容詞。「さい」は言い切りに直すと「さく」(ウ段)→ 動詞。', '自立語で活用しないもの:「花」は「花が」と主語になれる → 名詞。'], a: '美しい=形容詞/花=名詞/が=助詞/さい=動詞/た=助動詞', check: '5つの単語の品詞を全部合わせると、自立語3つ・付属語2つになり、文節の数(3)と自立語の数が一致することを確かめる。' }] },
      { h: '用言の見分けは「言い切りの形」で', t: '動詞・形容詞・形容動詞をまとめて【用言】といいます。どれも活用し、1語で述語になれる自立語です。\n用言は、文の中ではいろいろな形に変わっているので、そのままの形では見分けられません。必ず【言い切りの形(終止形)】に直してから判断します。言い切りの形とは、「。」をつけて文を終えるときの形です。\n例:「書か(ない)」→ 書く(ウ段)→ 動詞\n「高かっ(た)」→ 高い(い)→ 形容詞\n「静かに(歩く)」→ 静かだ(だ)→ 形容動詞\n言い切りの形に直すコツは、その語のすぐ後ろに「。」を置いて、自然な形に言い直すことです。\n動詞の言い切りは、書く(ku)・見る(ru)・する(ru)・泳ぐ(gu)のように、最後がすべてウ段の音になります。',
        key: '用言は必ず言い切りの形(「。」で終わる形)に直してから、ウ段・い・だ で見分ける。',
        ex: [{ q: '「静かに歩く」の「静かに」、「高かった」の「高かっ」の品詞は?', hint: 'それぞれの語のあとに「。」を置いて、言い切りの形に直そう。', steps: ['「静かに」を言い切りの形にすると「静かだ。」。「だ」で終わる。', '「だ」で終わる用言は形容動詞。前に「とても」をつけて「とても静かだ」と言えることでも確かめられる。', '「高かっ」を言い切りの形にすると「高い。」。「い」で終わる → 形容詞。'], a: '静かに=形容動詞、高かっ=形容詞', check: '「静かな部屋」「高ければ」のように別の形にも変えてみて、同じ語が活用していることを確かめる。' }] },
      { h: 'まちがえやすい品詞の見分け', t: '【「大きな」と「大きい」】\n「大きい」は「大きかった・大きければ」と活用するので形容詞。\n「大きな」は形が変わらず、「大きな木」のように名詞の前にしか使えないので連体詞。「小さな」「おかしな」も連体詞です。\n【形容動詞と「名詞+だ」】\n「静かだ」と「学生だ」は、どちらも「だ」で終わります。見分けは2つ。\n・前に「とても」をつけられるか:とても静かだ(○)/とても学生だ(×)\n・「〜な+名詞」にできるか:静かな部屋(○)/学生な人(×)\nどちらもできれば形容動詞、できなければ「名詞+助動詞だ」です。\n【「ある」の2つの顔】\n「本がある」の「ある」は、「あった・あれば」と活用し、述語になっているので動詞。\n「ある日のこと」の「ある」は、形が変わらず「日」をくわしくするだけなので連体詞。\n【「きれい」のわな】\n「きれい」は「い」で終わるので形容詞に見えますが、言い切りの形は「きれいだ」です。「きれかった」とは言えないので、形容動詞です。',
        key: '「大きな・小さな」は連体詞、「きれいだ」は形容動詞。「とても」「〜な+名詞」で形容動詞を確かめる。',
        ex: [{ q: '「きれいな花」の「きれいな」、「大きな箱」の「大きな」の品詞は?', hint: 'それぞれ活用するかどうか、言い切りの形がどうなるかを考えよう。', steps: ['「きれいな」:言い切りの形に直すと「きれいだ」。「とてもきれいだ」とも言えるので形容動詞。', '「きれい」は「い」で終わるが、「きれかった」とは言えないので形容詞ではない。', '「大きな」:「大きだ」「大きなかった」のような形にならず、活用しない。', '活用しない自立語で、名詞「箱」だけをくわしくしている → 連体詞。'], a: 'きれいな=形容動詞、大きな=連体詞', check: '「大きい箱」なら「大きかった」と活用できるので形容詞になる。「大きな」と「大きい」の品詞がちがうことを比べて確かめる。' }] }
    ],
    faq: [['文節と単語は、どうちがうの?', '文節は「ネ」を入れて区切れる、発音上の自然なまとまりです。単語は、それをさらに意味をもつ最小の単位に分けたものです。\nたとえば「花が」は1文節ですが、単語にすると「花」と「が」の2つになります。'], ['どうして「大きな」は形容詞ではないの?', '形容詞は活用する(形が変わる)語だからです。「大きな」は、「大きなかった」「大きなければ」のように形を変えることができません。\n活用しない自立語で、名詞だけをくわしくするので、連体詞になります。意味が似ていても、品詞は「形が変わるかどうか」で決まります。'], ['副詞と連体詞の見分けがつきません。', 'くわしくする相手で見分けます。用言(動詞・形容詞・形容動詞)をくわしくするのが副詞、名詞だけをくわしくするのが連体詞です。\n例:「ゆっくり歩く」の「ゆっくり」は動詞「歩く」をくわしくするので副詞。「この本」の「この」は名詞「本」をくわしくするので連体詞です。']],
    terms: [['文節', '「ネ」を入れて区切れる、意味の分かる最小のまとまり'], ['単語', '意味をもつ言葉の最小の単位'], ['自立語', 'それだけで文節を作れる単語'], ['付属語', '自立語のあとについて使われる単語(助詞・助動詞)'], ['活用', '後ろにつく言葉によって、語の形が変わること'], ['用言', '自立語で活用し、単独で述語になれる語(動詞・形容詞・形容動詞)'], ['体言', '活用せず、主語になれる自立語(名詞)'], ['修飾語', 'ほかの文節をくわしくする文節']],
    miss: ['「きれい」が「い」で終わるので形容詞だと思ってしまう。見た目で決めず、言い切りの形(きれいだ)に直してから判断する。', '「大きな・小さな」を形容詞にしてしまう。活用するかを必ず確かめる(活用しないので連体詞)。', '動詞の形が変わったもの(さい・書か など)を、そのままの形で判断して迷う。必ず言い切りの形に直す。', '文節に区切るとき、「は・を・が」を前の語から切りはなしてしまう。付属語は前の自立語といっしょに1文節になる。'],
    sum: ['文節は「ネ」で区切る。文節の先頭には必ず自立語がある。', '文節どうしには、主・述、修飾・被修飾、接続、独立、並立、補助の関係がある。', '品詞分けは「自立語か付属語か → 活用するか → 働き・言い切りの形」の順。', '付属語は、活用すれば助動詞、しなければ助詞。', '用言は言い切りの形で:ウ段=動詞、い=形容詞、だ=形容動詞。', '活用しない自立語は働きで:主語=名詞、用言を修飾=副詞、体言を修飾=連体詞、つなぐ=接続詞、独立=感動詞。'],
    next: '次は「接続語」の単元に進みましょう。品詞の一つである接続詞をはじめ、文と文をつなぐ言葉の働きが分かると、文章の流れが読めるようになります。'
  };

  L.j_h5 = {
    goal: '接続語(つなぎ言葉)と指示語の働きが分かり、文と文の関係から文章の論理を正しく読み取れるようになる。',
    intro: '接続語は、文章の中の【道路標識】のようなものです。「しかし」は「ここで向きが変わるよ」、「つまり」は「ここでまとめるよ」と教えてくれます。標識を見落とすと道に迷うように、接続語を読み飛ばすと、筆者の言いたいことを取りちがえてしまいます。',
    pre: '文章は、たくさんの文が集まってできています。1つ1つの文は、前の文と何かの関係でつながっています。たとえば「原因と結果」「反対の内容」「例をあげる」などです。\nこの関係を、言葉ではっきり示すのが【接続語】です。「だから」「しかし」「たとえば」などがその例です。品詞でいえば多くは【接続詞】ですが、「そのため」「その結果」のような言葉のまとまりも、同じ働きをするので接続語にふくめます。\nまた、「これ」「それ」のように、前に出た内容を指す言葉を【指示語】といいます。指示語も、文と文をつなぐ大切な役割をもっています。\n接続語と指示語を正しく読めると、長い文章でも「どこが大事か」「話がどう進んでいるか」が分かるようになります。',
    secs: [
      { h: 'なぜ接続語に注目するのか', t: '次の2つの文を比べてみましょう。\n「雨が降った。だから、試合は中止になった。」\n「雨が降った。しかし、試合は行われた。」\n前の文は同じなのに、接続語がちがうだけで、後ろの内容がまったく変わります。接続語は、【後ろにどんな内容が来るかを予告する】言葉なのです。\nこのため、接続語を見た時点で、次に来る内容を予想しながら読むことができます。「しかし」を見たら「前と反対のことが来るな」、「たとえば」を見たら「具体例が来るな」と予想できます。\n文章が難しく感じるときほど、接続語に印をつけながら読むと、話の流れが見えてきます。',
        key: '接続語は、後ろに来る内容を予告する言葉。見た時点で次の内容を予想しながら読む。' },
      { h: '接続語の7つの種類', t: '接続語は、前と後ろの関係によって、次の7つに分けられます。\n【順接】…前が原因・理由で、後ろが当然の結果。だから・したがって・それで・すると\n【逆接】…前から予想されることと反対のことが後ろに来る。しかし・だが・ところが・けれども\n【並立・累加】…前に並べる、つけ加える。また・そして・さらに・しかも\n【対比・選択】…前と後ろを比べる、どちらかを選ぶ。一方・または・それとも\n【説明・補足】…前の理由を述べたり、条件をつけ加えたりする。なぜなら・ただし・もっとも\n【言いかえ・例示】…前をまとめ直す、例をあげる。つまり・すなわち・たとえば\n【転換】…話題を変える。さて・ところで\n特に大事なのは、【順接と逆接】のちがいです。前の内容から「当然そうなる」ことが来れば順接、「予想とちがう」ことが来れば逆接です。',
        key: '前から当然そうなる内容が続けば順接(だから)、予想と反対の内容が続けば逆接(しかし)。' },
      { h: '空らん補充は「前後の関係」を言葉にする', t: '接続語を入れる問題は、次の手順で解きます。\n①空らんの【前の文】と【後ろの文】を、それぞれ短くまとめる。\n②2つの関係を自分の言葉で言う(「前が理由で後ろが結果」「前と反対」「前の例」など)。\n③その関係に当たる接続語を選ぶ。\nなぜこの手順が大事かというと、選択肢を1つずつ入れて「なんとなく自然か」で決めると、順接と逆接の両方が自然に読めてしまうことがあるからです。必ず関係を言葉にしてから選びます。\n「なぜなら」が入る場合は、後ろの文が「〜からだ」で終わることが多いので、文末も手がかりになります。',
        key: '空らんの前後を短くまとめ、関係を自分の言葉で言ってから接続語を選ぶ。',
        ex: [{ q: '「朝から強い雨が降っていた。(  )、試合は予定どおり行われた。」(  )に入る接続語は?', hint: '前の文から、ふつうはどうなると予想できるだろう。', steps: ['前:強い雨が降っていた。→ ふつうは「試合は中止だろう」と予想される。', '後ろ:試合は予定どおり行われた。→ 予想と反対のことが起きている。', '予想と反対のことが後ろに来る関係は「逆接」。逆接の接続語を選ぶ。'], a: 'しかし(ところが・だが なども可)', check: '「だから」を入れると「雨が降っていたから試合が行われた」となり、理由と結果がつながらないことを確かめる。' },
          { q: '「この町には古い寺が多い。(  )、東大寺や興福寺がある。」(  )に入る接続語は?', hint: '後ろの文は、前の文とくらべて「まとめ」か「具体的」か。', steps: ['前:古い寺が多い(まとめた言い方)。', '後ろ:東大寺・興福寺(具体的な寺の名前)。', 'まとめた内容の具体例を後ろであげている → 例示。'], a: 'たとえば', check: '「つまり」を入れると、具体例のほうが「まとめ」になってしまい、順番が逆になることを確かめる。' },
          { q: '「私は毎朝早く起きる。(  )、朝の時間は頭がよく働くからだ。」(  )に入る接続語は?', hint: '後ろの文の終わり方に注目しよう。', steps: ['後ろの文が「〜からだ」で終わっている → 前の内容の理由を後ろで説明している。', '前の結果(早く起きる)のあとに理由をつけ足す関係は「説明」。', '説明の接続語は「なぜなら」。'], a: 'なぜなら', check: '2つの文を入れかえて「朝は頭がよく働く。だから、早く起きる。」と順接で言いかえられることを確かめる。' }] },
      { h: '筆者の主張は接続語のあとに来る', t: '説明文・論説文では、接続語が主張のありかを教えてくれます。\n・【しかし】のあと…前で一般的な考えを紹介し、「しかし」のあとで筆者が自分の考えを述べることが多いです。\n・【つまり・すなわち】のあと…前の内容のまとめ。大事なことが短く言い直されています。\n・【たとえば】のあと…具体例。主張を分かりやすくするための材料で、主張そのものではありません。\n・【AではなくB】…筆者が言いたいのは、否定されたAではなく【B】です。\n・【たしかにA。しかしB】…Aは相手の考えを一度認める部分(譲歩)。主張はB。\nなぜ筆者はこんな書き方をするのでしょうか。一般的な考えや反対意見を先に出し、それを乗りこえる形で自分の意見を言うと、読む人を説得しやすいからです。',
        key: '主張は「しかし」「つまり」のあと、「AではなくB」のB、「たしかにA。しかしB」のBに来る。',
        ex: [{ q: '「勉強で大切なのは、長い時間机に向かうことではなく、学んだことを自分の言葉で説明できることだ。」筆者の主張は?', hint: '「AではなくB」の形を探そう。', steps: ['「AではなくB」の形になっている。', 'A=長い時間机に向かうこと(否定されている)。', 'B=学んだことを自分の言葉で説明できること → これが主張。'], a: '勉強で大切なのは、学んだことを自分の言葉で説明できることだ。', check: '「勉強で大切なのは長い時間机に向かうことだ」とすると、筆者が否定した内容になってしまうことを確かめる。' }] },
      { h: '指示語は「前」を探して当てはめる', t: '【指示語】は、「これ・それ・あれ・どれ」「この・その」「ここ・そこ」など、ものごとを指し示す言葉です。こ・そ・あ・どで始まるので、【こそあど言葉】とも呼ばれます。\n文章では、同じ言葉のくり返しをさけるために指示語が使われます。指示語が何を指すかが分からないと、文の意味が分かりません。\n指示内容の探し方:\n①指示語の【すぐ前】から順に、さかのぼって探す(指示内容はたいてい前にある)。\n②見つけた内容を、指示語の位置に【当てはめて】読み、意味が通るか確かめる。\n③答えるときは、指示語の後ろにつながる形(「〜こと」など)に整える。\n例:「彼は毎日日記をつけている。これは十年間続いている。」→「これ」=毎日日記をつけていること。',
        key: '指示内容はすぐ前からさかのぼって探し、指示語の位置に当てはめて確かめる。',
        ex: [{ q: '「祖母は庭で野菜を育てている。それが、祖母の元気のひけつだそうだ。」の「それ」が指す内容は?', hint: '「それ」のすぐ前の文を見よう。', steps: ['「それ」のすぐ前の文を見る:祖母は庭で野菜を育てている。', '指示語の位置に当てはめる:「庭で野菜を育てていることが、祖母の元気のひけつだ」→ 意味が通る。', '「〜が」につながるように「〜こと」の形に整える。'], a: '(祖母が)庭で野菜を育てていること', check: '答えを「それ」の位置に入れて読み直し、文として自然か確かめる。' }] }
    ],
    faq: [['「しかし」と「ところが」は、同じ意味なの?', 'どちらも逆接ですが、少し感じがちがいます。「しかし」は意見や考えを述べるときに広く使われ、「ところが」は予想外の出来事が起きたときによく使われます。\nテストで「逆接を選べ」と聞かれたら、どちらも逆接と考えてかまいません。'], ['接続語がない文章は、どうやって関係を読むの?', '接続語が書かれていなくても、文と文の間には必ず関係があります。2つの文の間に、自分で「だから」「しかし」などを入れてみて、どれが自然かを考えると関係が分かります。'], ['指示語の内容が、後ろにあることはないの?', 'まれにあります。「これは秘密だが、実は〜」のように、これから話す内容を先に「これ」と指すことがあります。\nただし、ほとんどの場合は前にあるので、まず前から探すのが基本です。']],
    terms: [['接続語', '文と文、語と語をつなぎ、その関係を示す言葉'], ['順接', '前が理由で、後ろが当然の結果になるつながり'], ['逆接', '前から予想されることと反対の内容が後ろに来るつながり'], ['譲歩', '反対の意見をいったん認めること(たしかに〜)'], ['例示', '具体的な例をあげること'], ['指示語', 'こそあど言葉。前に出た内容などを指し示す言葉'], ['転換', '話題を変えるつながり(さて・ところで)']],
    miss: ['「だから」と「しかし」を、前後の関係を考えずに雰囲気で選ぶ。必ず前後を短くまとめて、関係を言葉にしてから選ぶ。', '「たとえば」のあとの具体例を、筆者の主張だと思ってしまう。具体例は主張を支える材料で、主張はその前後のまとめの文にある。', '「たしかに〜」の部分を筆者の主張だと読んでしまう。譲歩のあとの「しかし」以降が主張だと覚える。', '指示語の内容を探すとき、遠くの目立つ言葉を選んでしまう。すぐ前から順にさかのぼり、当てはめて確かめる。'],
    sum: ['接続語は文章の道路標識。後ろの内容を予告する。', '7つの種類のうち、順接と逆接のちがいが最重要。', '空らん補充は、前後の関係を言葉にしてから選ぶ。', '主張は「しかし」「つまり」のあと、「AではなくB」のBに来やすい。', '指示語の内容は、すぐ前から探して当てはめて確かめる。'],
    next: '次は「敬語」の単元に進みましょう。文の組み立てが分かってきたら、「だれの動作か」をつかんで正しい言葉づかいを選ぶ練習をすると、文法の力がさらに確かになります。'
  };

  L.j_keigo = {
    goal: '尊敬語・謙譲語・丁寧語のちがいが分かり、「だれの動作か」から正しい敬語を選べるようになる。',
    intro: '敬語は、相手を大切に思う気持ちを言葉の形で表すしくみです。いちばん大事なのは、【その動作をするのはだれか】を確かめることです。目上の人がする動作なら相手を高める尊敬語、自分(や身内)がする動作なら自分を低める謙譲語を使います。この1点を毎回確認するだけで、ほとんどのまちがいは防げます。',
    pre: '【目上の人】とは、年れいや立場が自分より上の人のことです。先生、先ぱい、お客様、初めて会う大人などがこれに当たります。\n文の中で、ある動作を【する人】のことを、その動作の【主語(動作主)】といいます。「先生が話す」なら、話す動作をするのは先生です。\n敬語では、もう1つ、【ウチとソト】という考え方が大切です。ウチは自分の側の人(家族、自分の学校や会社の人)、ソトはそれ以外の人です。ソトの人と話すときは、ウチの人は目上でも「自分の側」としてあつかいます。\nそして、言葉には「ていねいな言い方」と「ふつうの言い方」があります。「行きます」と「行く」のちがいです。敬語は、このていねいさを、場面や相手に合わせて使い分けるしくみです。',
    secs: [
      { h: '敬語の3つの種類', t: '敬語には、高める相手や方法のちがいによって、3つの種類があります。\n【尊敬語】…目上の人(相手や話題の人)の動作やようすを【高める】言い方。例:先生がお話しになる、先生が来られる\n【謙譲語】…自分や身内の動作を【へりくだり(低め)】、その動作を受ける相手を高める言い方。例:私がお持ちする、私がご案内する\n【丁寧語】…聞き手に対して、言い方を【ていねいにする】言い方。例:これは本です、そうでございます\nたとえるなら、尊敬語は「相手を持ち上げる」、謙譲語は「自分が下がって相手を立てる」、丁寧語は「話し方全体をていねいにする」働きです。\nなお、「お茶」「ご飯」のように、ものごとを上品に言う言い方を【美化語】と呼びます。また、国の「敬語の指針」(2007年)では、謙譲語を2つに分けて全部で5種類とする分け方も示されていますが、中学ではまず3種類を確実に使い分けられることが大切です。',
        key: '尊敬語=相手の動作を高める、謙譲語=自分側の動作をへりくだる、丁寧語=聞き手にていねいに言う。' },
      { h: '尊敬語と謙譲語の作り方', t: '特別な形がない動詞でも、決まった形にあてはめれば敬語にできます。\n【尊敬語の作り方】\n①【お(ご)〜になる】例:話す → お話しになる、出席する → ご出席になる\n②【〜れる・られる】例:話す → 話される、来る → 来られる\n③【お(ご)〜ください】(相手に頼むとき)例:お待ちください、ご記入ください\n【謙譲語の作り方】\n①【お(ご)〜する】例:持つ → お持ちする、案内する → ご案内する\n②【お(ご)〜いたす】(さらにていねい)例:お届けいたします\nここで注意したいのは、「お〜になる」と「お〜する」は形がよく似ていることです。「お〜に【なる】」は尊敬、「お〜【する】」は謙譲、と最後の言葉で見分けます。\n「お」と「ご」の使い分けは、ふつう、訓読みの和語には「お」(お話し・お持ち)、音読みの漢語には「ご」(ご案内・ご出席)をつけます。',
        key: '「お〜になる」は尊敬語、「お〜する」は謙譲語。最後の「なる」「する」で見分ける。',
        ex: [{ q: '「先生が、校長室で書類を書く」を、「お〜になる」を使った尊敬語の文にしよう。', hint: '書くのはだれか、まず確かめよう。', steps: ['書く動作をするのは先生(目上の人)→ 先生を高める尊敬語を使う。', '「書く」に「お〜になる」を当てはめる。「書く」の連用形「書き」を入れて「お書きになる」。', '文全体にもどす。'], a: '先生が、校長室で書類をお書きになる。', check: '「お書きする」にすると謙譲語になり、先生の動作を低めてしまうことを確かめる。' }] },
      { h: '特別な形の敬語(表で覚える)', t: 'よく使う動詞には、特別な形の敬語があります。特別な形があるときは、そちらを使うのがふつうです。(左が尊敬語、右が謙譲語)\n言う … 【おっしゃる】/【申す・申し上げる】\n行く … いらっしゃる・おいでになる/【参る・うかがう】\n来る … いらっしゃる・おいでになる・お見えになる・お越しになる/参る\nいる … いらっしゃる/おる\n見る … 【ご覧になる】/【拝見する】\n食べる … 【召し上がる】/【いただく】\nする … 【なさる】/【いたす】\n聞く … お聞きになる/うかがう・承る\n知る … ご存じだ/存じる・存じ上げる\n会う … お会いになる/お目にかかる\nくれる(相手が自分に)… くださる\nあげる(自分が相手に)… 差し上げる\nもらう(自分が相手から)… いただく\n覚えるコツは、【尊敬語と謙譲語をペアで】覚えることです。「見る=ご覧になる/拝見する」のように、左右をセットで声に出すと、取りちがえが減ります。',
        key: '特別な形は「尊敬語/謙譲語」をペアで覚える。特に、言う・行く・来る・見る・食べる・する。',
        ex: [{ q: '「先生が私の絵を見る」「私が先生の絵を見る」の「見る」を、それぞれ正しい敬語にしよう。', hint: 'それぞれ、見るのはだれかを確かめよう。', steps: ['1つ目:見るのは先生(目上)。目上の人の動作を高める → 尊敬語。', '「見る」の尊敬語は「ご覧になる」。', '2つ目:見るのは私(自分)。自分の動作をへりくだる → 謙譲語。', '「見る」の謙譲語は「拝見する」。'], a: '先生が私の絵をご覧になる/私が先生の絵を拝見する', check: '主語を入れかえて「先生が拝見する」と言うと、先生を低めてしまっておかしいことを確かめる。' },
          { q: '「(お客様に)どうぞ、温かいうちにいただいてください。」を正しく直そう。', hint: '食べるのはだれか。「いただく」は尊敬語・謙譲語のどちら?', steps: ['食べるのはお客様(目上・ソトの人)→ 尊敬語を使う必要がある。', '「いただく」は「食べる」の謙譲語なので、お客様の動作には使えない。', '「食べる」の尊敬語は「召し上がる」。頼む形にして「召し上がってください」。'], a: 'どうぞ、温かいうちに召し上がってください。', check: '「いただく」は自分が食べるとき(「私がいただきます」)に使う言葉であることを確かめる。' }] },
      { h: '丁寧語・美化語と、場面に合った使い方', t: '【丁寧語】は、話の内容に出てくる人ではなく、【いま話している相手(聞き手)】に対するていねいさを表します。「です・ます・ございます」が代表です。\n例:友達に「明日、先生がいらっしゃるよ」→ 先生への尊敬はあるが、友達への丁寧語はない。\n例:先生に「明日、父が参ります」→ 父をへりくだる謙譲語と、先生へのていねいさを表す丁寧語「ます」の両方を使っている。\nこのように、尊敬語・謙譲語(話題の人に対する敬意)と、丁寧語(聞き手に対する敬意)は、【組み合わせて】使うのがふつうです。\n【美化語】は、言葉そのものを上品にする言い方です。お茶、お水、ご飯、お弁当など。ただし、外来語(カタカナの言葉)には、ふつう「お」をつけません(×おコーヒー、とはふつう言わない)。',
        key: '丁寧語は聞き手へのていねいさ。尊敬語・謙譲語と組み合わせて使う。' },
      { h: 'まちがいやすい使い方', t: '敬語のまちがいは、ほとんどが次の4つのどれかです。\n【相手の動作に謙譲語を使う】\n× 先生が拝見する → ○ 先生がご覧になる\n× (お客様に)受付でうかがってください → ○ 受付でお尋ねください(「うかがう」は謙譲語なので、お客様の動作には使えない)\n【二重敬語】…同じ種類の敬語を重ねすぎる。\n× ご覧になられる(ご覧になる+られる)→ ○ ご覧になる\n× おっしゃられる → ○ おっしゃる\n【身内を高めてしまう】…家族や自分の学校・会社の人のことをソトの人に話すときは、身内を高めず、謙譲語を使う。\n× (電話で)父はいらっしゃいません → ○ 父はおりません\n【謙譲語に尊敬語をつける】\n× 先生が参られる → ○ 先生がいらっしゃる\nどれも、【だれの動作か】と【その人はウチかソトか】を確かめれば防げます。',
        key: 'まちがいの多くは、相手の動作に謙譲語、二重敬語、身内を高める、の3つ。主語とウチ・ソトを確かめる。',
        ex: [{ q: '次の文のまちがいを直そう。「(来客に)母が、すぐにいらっしゃいますので、こちらでお待ちしてください。」', hint: 'まちがいは2か所。それぞれの動作をするのはだれかを考えよう。', steps: ['「いらっしゃる」は母(身内)の動作。ソトの人に身内を高めてはいけない → 謙譲語「参る」に「ます」をつけて「参ります」にする。', '「お待ちする」は謙譲語(お〜する)。待つのはお客様なので尊敬語にする。', '「待つ」の尊敬語で頼む形は「お待ちください」。'], a: '母がすぐに参りますので、こちらでお待ちください。', check: '直した文で、母の動作は謙譲語、お客様の動作は尊敬語になっているかを確かめる。' },
          { q: '「校長先生がそうおっしゃられました。」を正しく直そう。', hint: '「おっしゃる」はもともと尊敬語。そこに何が重なっている?', steps: ['「おっしゃる」は「言う」の尊敬語。', 'そこに尊敬の「られる」を重ねている → 同じ種類の敬語を重ねた二重敬語。', '「られ」を取りのぞき、丁寧語「ました」をつける。'], a: '校長先生がそうおっしゃいました。', check: '「言われました」でも正しい(「言う」+尊敬の「れる」が1つだけ)ことも確かめる。' }] }
    ],
    faq: [['尊敬語と謙譲語は、どちらも相手を高めるのに、何がちがうの?', '尊敬語は、相手の動作そのものを高めます。謙譲語は、自分の動作を低めることで、その動作を受ける相手を立てます。\nつまり、使う場面がちがいます。相手が動作をするなら尊敬語、自分が動作をするなら謙譲語です。'], ['自分の親のことを話すとき、なぜ「お父さん」と言わないの?', 'ソトの人に話すとき、自分の家族はウチの人なので、高めずに話すのがきまりだからです。\nそのため「父・母」と言い、動作には謙譲語を使います(父が参ります、母が申しておりました)。家族どうしで話すときは「お父さん」でかまいません。'], ['「れる・られる」は、いつも尊敬語なの?', 'いいえ。「れる・られる」には、尊敬のほかに、受け身(先生にほめられる)、可能(朝早く起きられる)、自発(昔が思い出される)の意味もあります。\n尊敬かどうかは、主語が目上の人で、その人の動作を高めているかどうかで判断します。']],
    terms: [['尊敬語', '目上の人の動作を高める敬語(おっしゃる・いらっしゃる)'], ['謙譲語', '自分側の動作をへりくだり、動作を受ける人を高める敬語(申す・拝見する)'], ['丁寧語', '聞き手にていねいに言う敬語(です・ます・ございます)'], ['美化語', 'ものごとを上品に言う言い方(お茶・ご飯)'], ['二重敬語', '同じ種類の敬語を重ねた、まちがった言い方(おっしゃられる など)'], ['ウチとソト', '自分の側の人(家族など)と、それ以外の人。ソトの人にはウチの人を高めない']],
    miss: ['目上の人の動作に謙譲語を使う(先生が拝見する、先生が参る)。動詞を見たら、まず主語がだれかを確かめる。', '「お〜する」(謙譲語)を相手の動作に使う(お待ちしてください)。相手に頼むときは「お〜ください」と覚える。', 'ソトの人に向かって身内を尊敬語で高める(父がいらっしゃいます)。電話や来客の場面では、家族はウチの人と意識する。', '「られる」を重ねて二重敬語にしてしまう。特別な形の尊敬語(おっしゃる・ご覧になる)には、それ以上何もつけない。'],
    sum: ['敬語は「だれの動作か」を最初に確かめる。', '目上の人の動作=尊敬語、自分側の動作=謙譲語、聞き手へのていねいさ=丁寧語。', '「お〜になる」は尊敬、「お〜する」は謙譲。', '特別な形(おっしゃる/申す、ご覧になる/拝見する など)はペアで覚える。', '二重敬語と、身内を高める言い方に注意する。'],
    next: '次は「古文・和歌」の単元に進みましょう。古文の世界にも敬語がたくさん出てきます。いま学んだ「だれの動作か」を考える力は、古文で省略された主語を見つけるときにも役立ちます。'
  };

  // ===== 古文・漢文(中学) =====
  L.j_kobun_m = {
    goal: '歴史的仮名遣いを現代仮名遣いに直し、係り結びのきまりを知り、有名な古典作品の冒頭と作者、和歌の修辞が分かるようになる。',
    intro: '古文は、昔の日本語で書かれた文章です。外国語ではないので、【書き方のちがい】と【少しのきまり】を知れば、意外なほど読めるようになります。この単元では、①昔の仮名の書き方(歴史的仮名遣い)、②文末の形が変わるきまり(係り結び)、③教科書に出てくる有名な作品、④和歌の修辞、を学びます。',
    pre: '【古文】とは、おもに平安時代から江戸時代ごろまでの、昔の日本語で書かれた文章のことです。時代の順番は、奈良時代 → 平安時代 → 鎌倉時代 → 室町時代 → 安土桃山時代 → 江戸時代、です。教科書によく出る作品の多くは、平安時代と鎌倉時代のものです。\n古文と今の日本語のちがいは、大きく3つあります。①仮名の書き方がちがう(歴史的仮名遣い)、②今とはちがう言葉や意味がある(古語)、③文法(文の終わり方など)が少しちがう、です。\n平安時代には【ひらがな】が広く使われるようになり、女性たちが日記や物語を書きました。『枕草子』や『源氏物語』はその代表です。\n古文を読むときは、注(本文の横や下にある説明)と現代語訳が大きな助けになります。最初は現代語訳と見比べながら、声に出して読むことから始めましょう。',
    secs: [
      { h: '歴史的仮名遣いを直す', t: 'なぜ書き方がちがうのでしょうか。昔の人は、当時の発音どおりに仮名を書いていました。ところが、発音は長い年月で変わっていき、書き方だけが昔のまま残りました。そこで、読むときは【今の発音】に直して読みます。\n①語の頭以外の【は・ひ・ふ・へ・ほ → わ・い・う・え・お】。例:いふ → いう、にほひ → におい\n②【ゐ → い、ゑ → え、を → お】(を は助詞以外)。例:をかし → おかし、こゑ → こえ\n③【ぢ → じ、づ → ず】。例:よろづ → よろず\n④母音が続くとき:【あう(あふ)→ おう】、【いう(いふ)→ ゆう】、【えう(えふ)→ よう】。例:やうやう → ようよう、けふ → きょう\n⑤【くわ → か、ぐわ → が】。例:くわじ(火事)→ かじ\n⑥助動詞・助詞の【む → ん】。例:行かむ → 行かん\nルールは1つだけで止めず、当てはまるものを【順に全部】使います。たとえば「けふ」は、①で「けう」、④で「きょう」になります。',
        key: '語の頭以外のハ行はワ行に。ルールは1つで止めず、当てはまるものを順に全部使う。',
        ex: [{ q: '「やうやう」「にほひ」「をかし」を現代仮名遣いに直そう。', hint: 'どのルールが当てはまるか、1文字ずつ見よう。', steps: ['やうやう:「やう」は「や+う」で、母音 a+u が続く → ④で「よう」。くり返して「ようよう」。', 'にほひ:語の頭以外の「ほ」→「お」、「ひ」→「い」(ルール①)で「におい」。', 'をかし:「を」は助詞ではないので → ②で「お」にして「おかし」。'], a: 'ようよう/におい/おかし', check: '直した言葉を声に出して読み、今の言葉(ようやく・におい・おかしい)とつながるか確かめる。' },
          { q: '「てふてふ」(蝶)を現代仮名遣いに直そう。', hint: 'ルールを2段階で使うよ。', steps: ['まず①:語の頭以外の「ふ」は「う」→「てう」「てう」で「てうてう」。', '次に④:「てう」は母音 e+u が続く「えう」の形 → 「ちょう」になる(「けふ→きょう」と同じ変化)。', 'くり返して「ちょうちょう」。'], a: 'ちょうちょう', check: '意味が「蝶」なので、今の言葉「ちょうちょう」と一致することを確かめる。' }] },
      { h: '係り結び', t: '文の中に【ぞ・なむ・や・か・こそ】という助詞(係りの助詞)があると、文末の形が変わります。これを【係り結び】といいます。\nなぜそんなきまりがあるのでしょうか。強めたり問いかけたりする気持ちを、文の途中の助詞と文末の形の【両方で】表すためです。\n・【ぞ・なむ・や・か】→ 文末が【連体形】になる。\n・【こそ】→ 文末が【已然形】になる。\n(連体形・已然形は、言葉の形の種類の名前です。今は「ふつうの終わり方とはちがう形になる」と分かれば十分です。)\n意味:ぞ・なむ・こそ は【強調】(訳すときは特に訳さなくてよい)。や・か は【疑問・反語】(〜か。/〜だろうか、いや〜ない)。\n例:ふつうの文「いひけり」(言った)\n→「となむいひける」(けり が連体形 ける に)\n→「とこそいひけれ」(けり が已然形 けれ に)\n文末が「けり」ではなく「ける」「けれ」になっていたら、前に係りの助詞がないか探すくせをつけましょう。',
        key: 'ぞ・なむ・や・か → 文末は連体形、こそ → 文末は已然形。',
        ex: [{ q: '『竹取物語』の一節「名をば、さぬきの造となむいひける。」の「いひける」が「いひけり」でないのはなぜ?', hint: '文の中に、係りの助詞がないか探そう。', steps: ['文の中に係りの助詞を探す →「なむ」がある。', '「なむ」は、文末を連体形にする係りの助詞。', '過去の助動詞「けり」の連体形は「ける」。だから文末が「いひける」になっている。'], a: '係りの助詞「なむ」があるため、係り結びで文末が連体形「ける」になっているから。', check: '「なむ」を取りのぞいた文「名をば、さぬきの造といひけり。」が、ふつうの終わり方になることを確かめる。' },
          { q: '『徒然草』序段の終わり「あやしうこそものぐるほしけれ」は、係り結びになっている。係りの助詞と、結びの語を答えよう。', hint: '「こそ」の結びは何形だったかな。', steps: ['係りの助詞を探す →「こそ」がある。', '「こそ」の結びは已然形。文末の「ものぐるほしけれ」が、その已然形の結び(終止形なら「ものぐるほし」)。', '強調なので特に訳さず、「妙に正気を失ったような気持ちがする」くらいに訳す。'], a: '係りの助詞=こそ、結び=ものぐるほしけれ(已然形)', check: '文末が「〜けれ」という、ふつうの言い切り(〜し)とはちがう形で終わっていることを確かめる。' }] },
      { h: '有名な作品と冒頭', t: '教科書や入試によく出る作品です。作者・時代・ジャンル・冒頭をセットで覚えます。\n【竹取物語】(平安時代・作者不明・物語)「今は昔、竹取の翁といふものありけり。」現存する日本最古の物語といわれます。\n【枕草子】(平安時代・清少納言・随筆)「春はあけぼの。やうやう白くなりゆく山ぎは、少しあかりて、紫だちたる雲の細くたなびきたる。」\n【平家物語】(鎌倉時代・作者不明・軍記物語)「祇園精舎の鐘の声、諸行無常の響きあり。」琵琶法師が語り伝えました。\n【方丈記】(鎌倉時代・鴨長明・随筆)「ゆく河の流れは絶えずして、しかももとの水にあらず。」\n【徒然草】(鎌倉時代末・兼好法師・随筆)「つれづれなるままに、日暮らし、硯にむかひて、……」\n【おくのほそ道】(江戸時代・松尾芭蕉・紀行文)「月日は百代の過客にして、行きかふ年もまた旅人なり。」\n枕草子・方丈記・徒然草は【三大随筆】と呼ばれます。平家物語の「諸行無常」(すべてのものは移り変わる)のように、作品をつらぬく考え方もいっしょに覚えると、内容の問題にも強くなります。',
        key: '作品は「時代・作者・ジャンル・冒頭」の4点セットで覚える。三大随筆=枕草子・方丈記・徒然草。',
        ex: [{ q: '次の冒頭文の作品名と作者を答えよう。①「つれづれなるままに、日暮らし、硯にむかひて」②「春はあけぼの。」', hint: 'どちらも三大随筆のひとつ。', steps: ['①「つれづれなるままに」は、することがなく退屈なままに、という意味で始まる随筆 →『徒然草』。作品名の「徒然(つれづれ)」と冒頭が対応している。', '『徒然草』の作者は兼好法師(鎌倉時代末)。', '②「春はあけぼの」は、季節ごとに趣のある時間帯を挙げる随筆 →『枕草子』。作者は清少納言(平安時代)。'], a: '①徒然草・兼好法師 ②枕草子・清少納言', check: '作品名「徒然草」の読み「つれづれぐさ」と、冒頭「つれづれなるままに」が一致することを確かめる。' }] },
      { h: '主語を補って読む', t: '古文は主語がよく省略されます。昔の読み手には、話の流れや敬語で、だれの動作か分かったからです。今の私たちは、主語を自分で補いながら読む必要があります。\n手がかり1:【「〜て」「〜で」でつながっている間は、ふつう主語は変わらない】。\n例:「(翁は)野山にまじりて竹を取りつつ、よろづのことに使ひけり。」→ まじる・取る・使う、すべて翁の動作。\n手がかり2:【「〜を」「〜に」「〜ど」「〜ば」のあとでは、主語が変わることがある】ので、だれの動作かを確かめ直します。\n手がかり3:【敬語】。尊敬語が使われている動作は、身分の高い人の動作であることが多いです。\n手がかり4:【会話の「 」】。「 」の前後で、話す人と聞く人を確かめます。「 」のあとの「と言ふ」「とて」はだれの動作かを考えます。\n分からなくなったら、注や現代語訳で人物を確かめ、本文に( )で主語を書きこみながら読みましょう。',
        key: '「〜て」でつながる間は主語は同じ。「〜を・に・ど・ば」のあとは主語が変わることがある。' },
      { h: '和歌の修辞:枕詞と掛詞', t: '【和歌】は、五・七・五・七・七の31音でよむ歌です(今の短歌と同じ形)。和歌には、短い言葉に多くの意味をこめるための工夫(修辞)があります。\n【枕詞】…決まった言葉の前に置く、ふつう5音の飾りの言葉。調子を整えたり、雰囲気を出したりします。意味は訳さなくてよいです。\n例:【あしひきの】→ 山、【ひさかたの】→ 光・天・空、【たらちねの】→ 母、【ちはやぶる】→ 神、【あをによし】→ 奈良\n【掛詞】…1つの言葉に、同じ音の2つの意味を重ねる技法。今の「しゃれ」に近いですが、歌の世界を広げるための工夫です。\n例:小野小町「花の色はうつりにけりないたづらにわが身世にふるながめせしまに」(『古今和歌集』)\n「ふる」=(長雨が)降る/(年月を)経る、「ながめ」=長雨/眺め(物思いにふける)。花の色があせることと、自分が年を重ねることを重ねています。\n枕詞は「決まった組み合わせを覚える」、掛詞は「同じ音で2つの意味がないか考える」と覚えましょう。',
        key: '枕詞は決まった言葉の前の飾り(訳さない)。掛詞は同じ音に2つの意味を重ねる。',
        ex: [{ q: '紀友則の和歌「ひさかたの光のどけき春の日にしづ心なく花の散るらむ」の枕詞と、それがかかる言葉を答えよう。', hint: '最初の5音に注目しよう。', steps: ['和歌の最初の5音「ひさかたの」は、代表的な枕詞。', '「ひさかたの」は、光・天・空などにかかる。', 'すぐ後ろに「光」があるので、「ひさかたの」→「光」にかかっている。訳すときは「ひさかたの」は訳さない。'], a: '枕詞=ひさかたの、かかる言葉=光', check: '「ひさかたの」を取りのぞいても、「光ののどかな春の日に…」と歌の意味が通ることを確かめる。' }] }
    ],
    faq: [['古文は、どうして今と書き方がちがうの?', '書き方は昔の発音にもとづいて決まったのに、発音のほうが時代とともに変わったからです。\n明治時代以降も長く歴史的仮名遣いが使われ、今の書き方のもとになる「現代かなづかい」が定められたのは1946年(昭和21年)です。'], ['係り結びの「連体形」「已然形」がよく分かりません。', '古文の動詞や助動詞は、後ろにつく言葉によって形が変わります。その形の種類に名前がついていて、連体形・已然形はその一部です。\n中学では、「ぞ・なむ・や・か があると文末が〜ける・〜る などの形に、こそ があると〜けれ・〜れ などの形になる」と分かれば十分です。くわしくは高校の古典文法で学びます。'], ['作品と作者は、全部覚えないといけないの?', 'まずは、竹取物語・枕草子・平家物語・方丈記・徒然草・おくのほそ道の6つを覚えましょう。\n作者が分かっている作品(枕草子=清少納言、方丈記=鴨長明、徒然草=兼好法師、おくのほそ道=松尾芭蕉)は、入試でよく問われます。']],
    terms: [['歴史的仮名遣い', '昔の発音をもとにした仮名の書き方'], ['係り結び', 'ぞ・なむ・や・か・こそ があると、文末の形が変わるきまり'], ['連体形', '体言(名詞)に続く形。ぞ・なむ・や・か の結び'], ['已然形', '「すでにそうなっている」形。こそ の結び'], ['随筆', '見聞きしたことや感じたことを、自由に書いた文章'], ['枕詞', '決まった言葉の前に置く、ふつう5音の飾りの言葉'], ['掛詞', '1つの言葉に、同じ音の2つの意味を重ねる和歌の技法']],
    miss: ['語の頭の「は・ひ・ふ・へ・ほ」まで「わ行」で読んでしまう(はな → わな としない)。「語の頭以外」という条件を必ず確かめる。', '「けふ」を「けう」で止めてしまう。ルールは1つで終わらせず、最後まで当てはめて「きょう」にする。', '係り結びで、こそ の結びを連体形にしてしまう。「こそ → 已然形(〜けれ)」だけ別、と覚える。', '枕草子と徒然草の作者を入れかえる。枕草子=清少納言(平安)、徒然草=兼好法師(鎌倉末)と、時代もいっしょに覚える。'],
    sum: ['歴史的仮名遣いは6つのルールを順に当てはめる。', 'ぞ・なむ・や・か → 連体形、こそ → 已然形。ぞ・なむ・こそ は強調、や・か は疑問・反語。', '作品は「時代・作者・ジャンル・冒頭」をセットで覚える。', '主語は「〜て」の間は同じ、「〜を・に・ど・ば」のあとで変わることがある。', '枕詞は訳さない飾り、掛詞は同じ音に2つの意味。'],
    next: '次は「漢文」の単元に進みましょう。漢文も古典の一つで、返り点という目印を使って読みます。古文で身につけた「昔の文章を今の言葉に直す」感覚が、そのまま役立ちます。'
  };

  L.j_kanbun_m = {
    goal: '返り点(レ点・一二点)に従って漢文を読む順番が分かり、書き下し文に直せるようになる。漢詩の形と、代表的な故事成語の意味と由来も分かるようになる。',
    intro: '漢文は、昔の中国の文章を、日本人が日本語として読めるように工夫したものです。中国語は「読書(書を読む)」のように【動詞が先、目的語が後】の順なので、日本語の語順にするには、読む順番を入れかえる必要があります。そのための目印が【返り点】です。',
    pre: '【漢文】とは、昔の中国の文語(書き言葉)で書かれた文章です。中国の古典である『論語』や、唐の時代の詩(漢詩)などが教科書によく出ます。\n日本語と中国語では、言葉の並べ方(語順)がちがいます。日本語は「私は 本を 読む」と、動作を表す言葉が最後に来ます。中国語は「我 読 書(私は 読む 本を)」と、動作のすぐあとに「何を」が来ます。英語の I read books. と同じ順番です。\nそこで昔の日本人は、漢字の文章はそのままに、小さな記号と仮名を書きこんで、日本語の順番で読む方法を考えました。これを【訓読】といいます。\n訓読で使う記号には、読む順番を示す【返り点】(漢字の左下に書く)と、日本語の活用語尾や助詞を補う【送り仮名】(漢字の右下にカタカナで書く)があります。\n書き下すときは、古文と同じ【歴史的仮名遣い】を使います。たとえば「言ふ」「習ふ」のように書きます。',
    secs: [
      { h: '白文・訓読文・書き下し文', t: '漢文には、3つの姿があります。\n【白文】…漢字だけで書かれた、もとの中国の文。例:読書\n【訓読文】…白文に、返り点と送り仮名をつけたもの。日本語として読むための目印つき。\n【書き下し文】…訓読文を、そのとおりの順番で、漢字かな交じりの日本語の文に書き直したもの。例:書を読む\nつまり、白文 →(記号をつける)→ 訓読文 →(日本語の文にする)→ 書き下し文、という流れです。\nテストでは、「訓読文を書き下し文に直す」問題と、「書き下し文に合うように返り点をつける」問題がよく出ます。どちらも、【読む順番】が分かれば解けます。',
        key: '白文=漢字だけ、訓読文=返り点・送り仮名つき、書き下し文=日本語の文に直したもの。' },
      { h: 'レ点:すぐ下の1字から返る', t: '返り点の基本ルールは、「【返り点のない字は上から順に読む。返り点のある字は、いったん飛ばして後で読む】」です。\n【レ点】…すぐ下の1字を先に読んでから、レ点のついた字に1字だけ返ります。\n例:読レ書 →「読」にレ点があるので飛ばし、「書」(1)を読んでから「読」(2)に返る → 書を読む\nレ点が続けてついているときは、下から順に1字ずつ返ります。\n例:不レ覚レ暁 →「不」も「覚」も飛ばし、「暁」(1)→「覚」(2)→「不」(3)。→ 暁を覚えず\nなぜ1字だけ返るのかというと、中国語では「動作+その対象」が隣り合って並ぶことが多く、それを日本語の順(対象+動作)にするには、1字入れかえるだけでよいからです。',
        key: 'レ点の字は飛ばして、すぐ下の1字を読んでから1字返る。レ点が続けば下から順に返る。',
        ex: [{ q: '「春眠不 レ 覚 レ 暁」(孟浩然「春暁」の第1句)を書き下そう。「不」は打消の「ず」と読む。', hint: '返り点のない字から読み、レ点の字は飛ばそう。', steps: ['「春」「眠」には返り点がない → 上から順に読む(1・2番目)。「春眠」。', '「不」にはレ点 → 飛ばす。「覚」にもレ点 → 飛ばす。', '「暁」には返り点がない → 3番目に読む。', 'レ点に従って1字ずつ返る:「覚」が4番目、「不」が5番目。', '順番は「春眠 → 暁 → 覚 → 不」。送り仮名を補い、「不」はひらがなの「ず」にする。'], a: '春眠暁を覚えず(春の眠りは心地よく、夜が明けたのにも気づかない)', check: '書き下し文の漢字の順(春・眠・暁・覚・不)が、自分で決めた読む順番と一致しているか確かめる。' }] },
      { h: '一・二点と上・下点:2字以上はなれて返る', t: 'レ点は1字しか返れません。2字以上はなれた字に返るときは、【一・二点】を使います。\n【一・二点】…一点のついた字まで読んでから、二点のついた字に返ります。三点があれば、さらに三点へ返ります。\n例:登二高山一 →「登」(二点)は飛ばし、「高」(1)「山」(2・一点)を読んでから「登」(3)に返る → 高山に登る\n【上・下点】…一・二点をふくむ部分をはさんで、さらに大きく返るときに使います(上点の字まで読んだら、下点の字へ返る)。\nレ点と一点が同じ字についた「レ」のような形もあります。その場合も、まずレ点に従って1字返り、そのあと一・二点の順に読みます。\n迷ったときは、【返り点のない字に番号を振る → 返り点のある字に、返る順で番号を振る】と、順番がはっきりします。',
        key: '一点のついた字まで読んだら、二点の字へ返る。返り点のない字から番号を振ると迷わない。',
        ex: [{ q: '「不 レ 入 二 虎穴 一」を、読む順に並べて書き下そう。', hint: '「不」はレ点、「入」は二点、「穴」は一点。', steps: ['「不」にはレ点 → すぐ下の「入」を先に読むので、いったん飛ばす。', '「入」には二点 → 一点の字まで読んでから返るので、飛ばす。', '「虎」には返り点がない → 1番目。「穴」(一点)を読む → 2番目。', '一点まで読んだので二点の「入」へ返る → 3番目。次にレ点で「不」へ返る → 4番目。', '「虎穴 → 入 → 不」の順。「不」は打消の「ず」と読み、ひらがなで書く。'], a: '虎穴に入らず(「虎穴に入らずんば虎子を得ず」の前半)', check: '意味が「虎の穴に入らない」となり、日本語として自然な順番になっているか確かめる。' }] },
      { h: '書き下し文のきまり', t: '漢文を、返り点と送り仮名に従って日本語の文に直したものを【書き下し文】といいます。次のきまりで書きます。\n①送り仮名は【ひらがな】で書く(訓読文ではカタカナだが、書き下し文ではひらがなにする)。\n②日本語の助詞・助動詞にあたる漢字は【ひらがな】にする。例:不(ず)、也(なり)、之(の)、者(は)、乎(や・か)\n③【置き字】(而・於・于・矣 など、日本語では読まない字)は書かない。置き字は、中国語では意味や調子を表しますが、日本語では送り仮名などでその意味を表すので、字としては読みません。\n④歴史的仮名遣いのまま書く(例:習ふ、説ばし)。\nなぜ②のきまりがあるのでしょうか。日本語では、助詞や助動詞はひらがなで書くのがふつうだからです。「不」を漢字のまま残すと、日本語の文として不自然になります。',
        key: '書き下し文では、送り仮名と助詞・助動詞にあたる字はひらがなに。置き字は書かない。',
        ex: [{ q: '『論語』の一節「学 而 時 習 レ 之、不 二 亦 説 一 乎」を書き下そう。(而は置き字)', hint: '置き字の「而」は読まない。レ点と一・二点の順に注意しよう。', steps: ['「学」→ 学びて。「而」は置き字なので読まない(前の「て」に意味がふくまれる)。', '「時」→ 時に。「習レ之」はレ点 →「之」を先に読み「之を習ふ」。', '「不二亦説一」→ 二点の「不」を飛ばし、「亦(また)」「説(よろこばし)」を読んでから「不」へ返る → 亦説ばしからず。', '「乎」→「や」と読み、ひらがなで書く。'], a: '学びて時に之を習ふ、亦説ばしからずや(学んで、折にふれて復習する、なんとうれしいことではないか)', check: '書き下し文に「而」が出てこないこと、「不」「乎」がひらがな(ず・や)になっていることを確かめる。' }] },
      { h: '漢詩の形', t: '【漢詩】は、中国の古い詩です。特に唐の時代に、決まった形の詩(近体詩)が完成しました。形は、【1句の字数】と【句の数】で決まります。\n・1句が5字 →【五言】、7字 →【七言】\n・4句でできている →【絶句】、8句でできている →【律詩】\n組み合わせて「五言絶句」「七言律詩」のように呼びます。\n例:孟浩然「春暁」…春眠暁を覚えず/処処啼鳥を聞く/夜来風雨の声/花落つること知る多少 → 1句5字・4句 → 五言絶句。\n絶句の4句は、【起・承・転・結】の流れで組み立てられることが多いです。起(歌いおこす)→ 承(受けつぐ)→ 転(場面を変える)→ 結(まとめる)。\nまた、決まった句の終わりに、似た響きの字をそろえる【押韻】というきまりがあります(原則として偶数句の終わり)。律詩では、3・4句目と5・6句目を【対句】にするきまりもあります。',
        key: '1句の字数(五言・七言)と句の数(絶句=4句・律詩=8句)で漢詩の形が決まる。',
        ex: [{ q: '杜甫「春望」は、1句が5字で、全部で8句ある。この詩の形を答えよう。', hint: '字数と句の数を、それぞれ名前に直そう。', steps: ['1句が5字 →「五言」。', '8句でできている →「律詩」(4句なら絶句)。', '2つを組み合わせる。'], a: '五言律詩', check: '「春望」の第1句「国破れて山河在り」がもとの漢文で「国破山河在」の5字であることを確かめる。' }] },
      { h: '代表的な故事成語', t: '【故事成語】は、中国の昔の出来事や物語(故事)からできた言葉です。漢文の授業では、そのもとになった話を読むことが多いです。話の筋と意味をセットで覚えます。\n【矛盾】…どんな盾も突き通す矛と、どんな矛も防ぐ盾を売る人が、「あなたの矛であなたの盾を突いたらどうなるか」と問われて答えられなかった話から。つじつまが合わないこと。(『韓非子』)\n【推敲】…唐の詩人 賈島が、詩の「僧は推す月下の門」を「敲く」にするか迷った話から。文章を何度も練り直すこと。\n【蛇足】…蛇の絵をかく競争で、先にかき終えた人が足までかき足して負けた話から。よけいなつけ足し。\n【五十歩百歩】…戦場で五十歩逃げた者が、百歩逃げた者を笑った話から。少しのちがいはあっても、本質は同じこと。(『孟子』)\n【漁夫の利】…しぎとはまぐりが争っている間に、漁師が両方を捕まえた話から。二者が争う間に、第三者が利益を得ること。',
        key: '故事成語は、もとの話と意味をセットで覚える。',
        ex: [{ q: '「テストで40点だった兄が、35点だった弟を笑っている。まさに(  )だ。」(  )に入る故事成語は?', hint: '「少しのちがいで相手を笑う」話を思い出そう。', steps: ['場面:点数に少しの差はあるが、どちらもよい点とはいえない。', '少しのちがいはあっても本質は同じ、という意味の故事成語を探す。', '五十歩逃げた兵士が百歩逃げた兵士を笑った話 → 五十歩百歩。'], a: '五十歩百歩', check: '兄=五十歩逃げた兵士、弟=百歩逃げた兵士に当てはめて、話の形が同じになるか確かめる。' }] }
    ],
    faq: [['返り点は、どうして漢字の左下につけるの?', '送り仮名を漢字の右下に書くので、記号が重ならないように左下に書く決まりになっています。\n縦書きで読むとき、返り点は「次にどこへ戻るか」を示す目印なので、字のすぐ下に小さく書かれています。'], ['置き字は、どうして読まないの?', '置き字は、中国語では意味や語調を表す字ですが、日本語では送り仮名や助詞でその意味を表せるからです。\nたとえば「学而時習之」の「而」は「そして」の意味ですが、「学びて」の「て」がその意味をになっているので、「而」自体は読みません。'], ['一・二点とレ点は、どちらを先に見ればいいの?', 'まず、返り点のない字を上から読んでいきます。そして、返り点のある字に来たら飛ばし、レ点なら1字下を読んだ直後に、一点なら一点の字を読んだ直後に返ります。\nレ点は「すぐ返る」、一・二点は「一まで読んでから返る」と覚えると、順番を整理しやすくなります。']],
    terms: [['白文', '返り点も送り仮名もついていない、漢字だけの文'], ['訓読', '漢文を日本語の語順と言葉で読むこと'], ['返り点', '読む順番を示す記号(レ点・一二点・上下点)'], ['送り仮名', '訓読で、漢字の右下にカタカナで書きそえる仮名'], ['書き下し文', '漢文を、漢字かな交じりの日本語の文に直したもの'], ['置き字', '書き下し文では書かない字(而・於・矣 など)'], ['絶句・律詩', '4句の漢詩と8句の漢詩'], ['故事成語', '中国の昔の出来事・物語からできた言葉']],
    miss: ['レ点の字を先に読んでしまう。レ点の字は「すぐ下の字を読んでから返る字」なので、いったん飛ばす。', '書き下し文で「不・也・之」を漢字のまま書く。日本語の助詞・助動詞にあたる字はひらがなにする。', '置き字の「而」まで書き下し文に書いてしまう。書く前に置き字(而・於・于・矣)がないか確かめる。', '絶句と律詩を逆に覚える。「絶句=4句(短い)、律詩=8句(長い)」と句の数で覚える。'],
    sum: ['漢文は、白文 → 訓読文 → 書き下し文の流れで読む。', '返り点のない字は上から読み、返り点のある字は飛ばして後で読む。', 'レ点は1字返る。一・二点は一の字まで読んでから二の字へ返る。', '書き下し文では、助詞・助動詞にあたる字はひらがなにし、置き字は書かない。', '漢詩は五言・七言と絶句・律詩の組み合わせで形が決まる。', '故事成語は、もとの話と意味をセットで覚える。'],
    next: '次は「詩・短歌・俳句」の単元に進みましょう。漢詩で学んだ「形のきまり」や「対句」は、日本の詩や短歌・俳句の表現技法を理解するときにも役立ちます。'
  };

  L.j_shiika = {
    goal: '詩・短歌・俳句のきまりと表現技法が分かり、作品の中で使われている技法とその効果を説明できるようになる。',
    intro: '詩や短歌・俳句は、短い言葉の中に、作者の感動や情景をぎゅっとつめこんだ文章です。そのために、たとえを使ったり、語順を入れかえたりと、さまざまな【表現の工夫(表現技法)】がされています。技法の名前と効果を知ると、「なぜこの言い方なのか」が見えてきます。',
    pre: '【詩】は、心が動いたこと(感動)を、リズムのある短い言葉で表した文章です。ふつうの文章(散文)とちがい、行を変えたり、言葉をけずったりして、印象を強くします。\n【短歌】と【俳句】は、日本で昔から作られてきた、音の数が決まった詩です。短歌は五・七・五・七・七の31音、俳句は五・七・五の17音でつくります。\nここでいう「音」は、文字の数ではなく、【声に出したときの拍の数】です。手をたたきながら読むと数えやすくなります。\n詩歌を読むときの基本は、①何が書かれているか(情景)、②作者はどんな気持ちか(心情)、③そのためにどんな工夫をしているか(表現技法)、の3つを順に考えることです。',
    secs: [
      { h: '音の数え方', t: '短歌・俳句では、音の数が大切です。音の数え方には、次のきまりがあります。\n①ふつうのかな1字は1音。例:さくら → さ・く・ら で3音\n②【小さい「ゃ・ゅ・ょ」(拗音)】は、前の字と合わせて1音。例:きゃ → 1音、しょうぎ → しょ・う・ぎ で3音\n③【小さい「っ」(促音)】は1音。例:きって → き・っ・て で3音\n④【「ん」(撥音)】は1音。例:みかん → み・か・ん で3音\n⑤【のばす音「ー」(長音)】は1音。例:ケーキ → ケ・ー・キ で3音\nつまり、②の拗音だけが「2文字で1音」になり、ほかの小さい字やのばす音は、それぞれ1音と数えます。手をたたきながら声に出して数えると、まちがえにくくなります。',
        key: '小さい「ゃ・ゅ・ょ」は前の字と合わせて1音。「っ・ん・ー」はそれぞれ1音。',
        ex: [{ q: '「チョコレート」は何音?', hint: '小さい「ョ」と、のばす音「ー」の数え方を思い出そう。', steps: ['1音ずつ区切る:チョ/コ/レ/ー/ト。', '「チョ」は拗音なので、2文字で1音。', 'のばす音「ー」は1音と数える。', '数えると 1+1+1+1+1 で5音。'], a: '5音', check: '手をたたきながら「チョ・コ・レ・ー・ト」と言い、5回たたくことを確かめる。' }] },
      { h: '表現技法の種類と効果', t: '表現技法は、名前だけでなく【効果(なぜそう書いたか)】とセットで覚えます。\n【直喩(明喩)】…「ようだ・みたいだ・ごとし」を使ってたとえる。たとえであることがはっきり分かる。例:雪のように白い肌\n【隠喩(暗喩)】…「ようだ」などを使わずにたとえる。言い切るので、印象が強くなる。例:君はぼくの太陽だ\n【擬人法】…人でないものを人のように表す。親しみや生き生きした感じが出る。例:風がささやく、花がほほえむ\n【倒置法】…ふつうの語順を逆にして、前に出した言葉を強める。例:行こう、海へ。\n【体言止め】…文や句の終わりを体言(名詞)で止める。余韻を残し、印象を強める。例:空に浮かぶ白い雲\n【反復】…同じ言葉をくり返して、リズムを生み、意味を強める。例:春が来た 春が来た\n【対句】…形や意味が対になる言葉を並べる。リズムが整い、対比がはっきりする。例:山は青く、海は深い\n【省略】…言葉を途中で止め、読み手に想像させる。例:もしもあのとき……',
        key: '「ようだ」があれば直喩、なければ隠喩。技法は名前と効果をセットで答える。',
        ex: [{ q: '次の表現技法を答えよう。①「人生は旅だ」②「星がまばたきをしている」③「美しいなあ、夕焼けの空は」', hint: 'たとえか、人のように表しているか、語順が逆か、を順に確かめよう。', steps: ['①人生を旅にたとえているが、「ようだ」を使っていない → 隠喩。', '②星は人ではないのに「まばたき」という人の動作で表している → 擬人法。', '③ふつうの語順は「夕焼けの空は美しいなあ」。語順が逆になっている → 倒置法。'], a: '①隠喩 ②擬人法 ③倒置法', check: '①に「ようだ」を入れて「人生は旅のようだ」とすると直喩になり、元の文には「ようだ」がないことを確かめる。' },
          { q: '三好達治の詩「土」(蟻が/蝶の羽をひいて行く/ああ/ヨットのやうだ)の最後の行で使われている表現技法は?', hint: '最後の行の「やうだ」は、今の言葉で「ようだ」。', steps: ['最後の行「ヨットのやうだ」は、歴史的仮名遣いで、今の「ヨットのようだ」。', '蟻が運ぶ蝶の羽を、ヨット(の帆)にたとえている。', '「ようだ」を使ったたとえなので、直喩。'], a: '直喩(明喩)', check: '「ようだ」を取ると「ヨットだ」となり、それなら隠喩になることと比べて確かめる。' }] },
      { h: '詩の種類と連', t: '詩は、使う言葉と形で分けます。\n・使う言葉:今の言葉 →【口語詩】、昔の言葉(文語)→【文語詩】\n・形:音の数(五音・七音など)に決まりがある →【定型詩】、決まりがない →【自由詩】\n組み合わせて「口語自由詩」「文語定型詩」のように言います。今の教科書の詩の多くは、口語自由詩です。\n詩の中で、1行あけて区切られたまとまりを【連】といいます。文章の段落のようなものです。連が変わるところで、場面や気持ちが変わることが多いので、連ごとに「何が書かれているか」をまとめながら読みます。\n詩の題名にも注目しましょう。題名が、詩全体のテーマや、作者がいちばん伝えたいことを表していることがよくあります。',
        key: '今の言葉か昔の言葉か(口語・文語)と、音数の決まりがあるか(定型・自由)で詩を分ける。' },
      { h: '短歌のきまりと句切れ', t: '【短歌】は、【五・七・五・七・七】の31音でつくる詩です。最初の五・七・五を【上の句】、残りの七・七を【下の句】といいます。5つの部分を、上から初句・二句・三句・四句・結句と呼びます。\n意味や調子のうえで、とちゅうで大きく切れるところを【句切れ】といいます。「。」をつけられるところ、「かな・けり・や」や命令形・終止形で言い切っているところが目印です。\n例:若山牧水「白鳥は 哀しからずや/空の青 海のあをにも 染まずただよふ」\n「哀しからずや」(悲しくないのだろうか)で意味が切れるので、【二句切れ】です。最後まで切れずに続く歌は【句切れなし】です。\n句切れを探すときは、上から読んでいき、【「。」を打っても意味が通るところ】を見つけます。音の区切り(五・七)と、意味の切れ目は別のものなので注意します。',
        key: '句切れは意味の切れ目。「。」を打てるところを探す。',
        ex: [{ q: '若山牧水の短歌「白鳥は哀しからずや空の青海のあをにも染まずただよふ」は何句切れ?', hint: '「。」を打てるところを探そう。', steps: ['五・七・五・七・七に分ける:白鳥は/哀しからずや/空の青/海のあをにも/染まずただよふ。', '意味が切れるところを探す:「白鳥は悲しくないのだろうか。」で問いかけが終わっている。', '「哀しからずや」は2句目なので、二句切れ。'], a: '二句切れ', check: '2句目のあとに「。」を打ち、前半と後半がそれぞれ意味のまとまりになっているか確かめる。' }] },
      { h: '俳句のきまり:季語と切れ字', t: '【俳句】は、【五・七・五】の17音でつくる、世界でいちばん短い詩の一つです。\n①【季語】…季節を表す言葉を1つ入れるのが原則です。季節は昔のこよみ(旧暦)で考えるため、今の感覚とずれるものがあります。例:蛙(春)、菜の花(春)、五月雨(夏)、蝉(夏)、天の川(秋)、名月(秋)、柿(秋)\n②【切れ字】…「や・かな・けり」など。そこで意味を切り、作者の感動の中心を表します。\n例:松尾芭蕉「古池や 蛙飛びこむ 水の音」→ 季語は蛙(春)、切れ字は「や」。\n例:正岡子規「柿くへば 鐘が鳴るなり 法隆寺」→ 季語は柿(秋)。\n音の数が17音より多いものを【字余り】、少ないものを【字足らず】といいます。また、五・七・五や季語にしばられない俳句を【自由律俳句】といいます。例:種田山頭火「分け入つても分け入つても青い山」',
        key: '俳句は季語(旧暦の季節)と切れ字(や・かな・けり)がポイント。切れ字に感動の中心がある。',
        ex: [{ q: '松尾芭蕉の「閑さや岩にしみ入る蝉の声」の季語と季節、切れ字を答えよう。', hint: '季節を表す言葉と、「や・かな・けり」を探そう。', steps: ['季節を表す言葉を探す →「蝉」。', '蝉が鳴くのは夏 → 季節は夏。', '「や・かな・けり」を探す →「閑さや」の「や」。ここで切れて、静けさへの感動を表している。'], a: '季語=蝉(夏)、切れ字=や', check: '「や」のところで句が切れ、「閑さ(静けさ)」が感動の中心になっていることを読み直して確かめる。' },
          { q: '松尾芭蕉の「五月雨をあつめて早し最上川」の季語と季節を答えよう。', hint: '「五月」とあるが、旧暦で考えよう。', steps: ['季節を表す言葉を探す →「五月雨(さみだれ)」。', '旧暦の五月は、今のこよみでいうと6月ごろ。五月雨は、その時期に降る長雨(梅雨)のこと。', '梅雨の時期なので、季節は夏。'], a: '季語=五月雨、季節=夏', check: '「五月」だから春、とせず、旧暦では4〜6月が夏であることを思い出して確かめる。' }] },
      { h: '詩歌の鑑賞:情景 → 心情 → 技法', t: '詩歌の問題で「この作品の鑑賞として正しいものを選べ」と聞かれたら、次の3段階で考えます。\n①【情景】…何が、どこで、どうなっているか。目に見える場面を思いうかべる。\n②【心情】…作者はその情景をどう感じているか。感動の中心はどこか(切れ字・句切れ・体言止めの部分に注目)。\n③【技法と効果】…その感動を伝えるために、どんな技法を使っているか。\n例:「古池や蛙飛びこむ水の音」\n①情景:古い池に蛙が飛びこみ、水の音がした。\n②心情:「や」で古池の静けさに感動している。一瞬の水の音が、かえって静けさを深く感じさせる。\n③技法:切れ字「や」、体言止め(水の音)。\n選択肢を選ぶときは、作品に書かれていない内容(作者の人生の話など)を勝手に加えたものに注意しましょう。',
        key: '鑑賞は「情景 → 心情 → 技法と効果」の順に考える。' }
    ],
    faq: [['直喩と隠喩は、どちらがすぐれているの?', 'どちらがすぐれているということはありません。効果がちがいます。\n直喩は、たとえであることがはっきりして分かりやすく、隠喩は、言い切ることで印象が強くなります。作者は伝えたい感じに合わせて使い分けています。'], ['季語の季節が今とずれるのはなぜ?', '俳句の季節は、昔のこよみ(旧暦)にもとづいているからです。旧暦では、1〜3月が春、4〜6月が夏、7〜9月が秋、10〜12月が冬で、今のこよみより1か月ほど季節が早く進みます。\nそのため、「天の川」「七夕」は秋、「五月雨」は夏になります。'], ['短歌と和歌は、何がちがうの?', '形はどちらも五・七・五・七・七で同じです。ふつう、昔の歌を「和歌」、明治時代以降に作られた近代・現代の歌を「短歌」と呼び分けます。']],
    terms: [['直喩', '「ようだ」などを使ったたとえ'], ['隠喩', '「ようだ」などを使わないたとえ'], ['擬人法', '人でないものを人のように表す技法'], ['体言止め', '文や句を名詞で終え、余韻を残す技法'], ['連', '詩の中で、1行あけて区切られたまとまり'], ['句切れ', '短歌・俳句で、意味や調子が大きく切れるところ'], ['季語', '俳句に入れる、季節を表す言葉'], ['切れ字', '「や・かな・けり」など、句を切って感動を表す言葉']],
    miss: ['「ように」があるのに隠喩と答える。答える前に、たとえの部分に「ようだ・ように・みたいだ」があるかを必ず確かめる。', '季語の季節を今の感覚で答える(天の川は秋、五月雨は夏)。旧暦は今より季節が早いと覚えておく。', '短歌の句切れを、音の区切り(五・七)と同じだと思ってしまう。句切れは「。」を打てる意味の切れ目で探す。', '音の数を文字の数で数えてしまう。拗音(ゃ・ゅ・ょ)は前の字と合わせて1音と数える。'],
    sum: ['音の数は拍で数える。拗音は2文字で1音、「っ・ん・ー」は1音。', '「ようだ」あり=直喩、なし=隠喩。人のように表す=擬人法。', '語順を逆にする=倒置法、名詞で終える=体言止め。', '短歌は五・七・五・七・七、句切れは意味の切れ目で探す。', '俳句は五・七・五、季語(旧暦)と切れ字(や・かな・けり)がポイント。', '鑑賞は「情景 → 心情 → 技法と効果」の順に考える。'],
    next: '次は「読解・作文」の単元に進みましょう。詩歌で練習した「情景から心情を読む」力は、小説や物語の読解でもそのまま使えます。'
  };

  L.j_dokkai = {
    goal: '文章の種類と構成をつかみ、説明文の要旨を短くまとめたり、小説の場面と心情を読み取ったり、自分の意見を型どおりに書いたりできるようになる。',
    intro: '長い文章を読むとき、1文ずつ同じ力で読んでいくと、何が大事なのか分からなくなります。文章には【骨組み(構成)】があり、どこに大事なことが書かれやすいかが決まっています。説明文なら「筆者の考えはどこか」、小説なら「気持ちがどう変わったか」をつかむための、読み方の型を学びます。',
    pre: '国語で読む文章は、大きく2つに分けられます。1つは、事実や考えを伝えるための【説明的文章】(説明文・論説文)。もう1つは、物語や体験を味わうための【文学的文章】(小説・物語・随筆など)です。\n【段落】とは、文章の中で、内容のまとまりごとに区切られた部分です。段落の初めは1字下げて書きます。\n文章を書いた人を【筆者】(説明文・随筆)や【作者】(小説・詩)といいます。説明文では、筆者がいちばん伝えたいことを【主張】や【要旨】と呼びます。\n読解問題の答えは、ほとんどの場合、【本文の中】に根拠があります。自分の考えや知識ではなく、本文のどこに書いてあるかを探して答えるのが基本です。',
    secs: [
      { h: '文章の種類と読み方のちがい', t: '文章の種類によって、読むときに注目するところがちがいます。\n【説明文】…あることがらについて、事実をもとに分かりやすく説明する文章。注目点:何について、どんな順序で説明しているか。\n【論説文】…ある問題について、筆者の意見(主張)を、理由をあげて述べる文章。注目点:筆者の主張と、その理由。\n【小説・物語】…作者が作った人物やできごとを描く文章。注目点:場面、人物の気持ちとその変化。\n【随筆】…筆者が見聞きしたことや体験をもとに、感じたこと・考えたことを自由に書いた文章。注目点:体験(事実)と、そこから生まれた感想・考え。\n最初に「この文章はどの種類か」を見きわめると、何を探しながら読めばよいかが決まります。',
        key: '説明的文章は「筆者の主張」、文学的文章は「人物の気持ちとその変化」を探しながら読む。' },
      { h: '段落と文章の構成', t: '【形式段落】…書き出しが1字下がっているところから、次の1字下がりまでのまとまり。\n【意味段落】…内容が同じ形式段落をまとめた、大きなまとまり。\n説明文・論説文の多くは、【序論・本論・結論】の3つでできています。\n・序論…話題や問題を示す(「〜だろうか」という問いかけが多い)。\n・本論…説明・具体例・理由をくわしく述べる。\n・結論…まとめと、筆者の考え(主張)を述べる。\n筆者の主張がどこにあるかで、次の3つの型に分けます。\n【頭括型】…主張が最初にある。\n【尾括型】…主張が最後にある。\n【双括型】…主張が最初と最後の両方にある。\n名前の「括」は「くくる(まとめる)」という意味です。「頭でまとめる」「尾(最後)でまとめる」「双方(両方)でまとめる」と覚えます。',
        key: '説明文は序論・本論・結論。主張の位置で頭括型・尾括型・双括型に分ける。',
        ex: [{ q: '「①読書は大切だ。②本を読むと、知らない言葉に出会える。③また、他人の考えにふれることもできる。④だから、読書は大切なのだ。」この文章の型は?', hint: '筆者の主張がどの段落にあるか探そう。', steps: ['①「読書は大切だ」は筆者の主張。', '②③は、読書が大切な理由(具体的な内容)。', '④「だから、読書は大切なのだ」で、もう一度主張をくり返している。', '主張が最初(①)と最後(④)の両方にある。'], a: '双括型', check: '①と④を並べると、どちらも同じ主張(読書は大切だ)になっていることを確かめる。' }] },
      { h: '要旨をつかむ手順', t: '【要旨】は、文章の中で筆者がいちばん言いたいこと(中心となる考え)です。文章全体を短くしたもの(要約)とはちがいます。\n手順:\n①各段落の【最初と最後の文】に線を引く(段落の中心の文が来やすい)。\n②「たとえば」で始まる具体例の部分は、いったん外す。\n③「つまり」「このように」「〜のではないだろうか」「〜べきだ」など、まとめや主張を表す言葉がある文を探す。\n④問いかけ(序論)と答え(結論)を組にして、1〜2文にまとめる。\nなぜ具体例を外すのでしょうか。具体例は、主張を分かりやすくするための材料だからです。材料をいくら集めても、主張そのものにはなりません。',
        key: '要旨は、具体例を外し、問いかけ(序論)と答え(結論)を組にして1〜2文にまとめる。',
        ex: [{ q: '次の文章の要旨をまとめよう。「①私たちは毎日たくさんの水を使っている。水は限りなくあるものなのだろうか。②たとえば、地球上の水のほとんどは海水で、人がそのまま使える淡水はごくわずかだ。③また、雨の量が少ない地域では、水不足が深刻になっている。④このように、使える水は限られている。だからこそ、私たちは水を大切に使う必要がある。」', hint: '問いかけの文と、「このように」で始まるまとめの文を探そう。', steps: ['①は序論。「水は限りなくあるのか」という問いかけ。', '②③は本論。「たとえば」「また」で、使える水が少ないことの具体例を並べている → 要旨からは外す。', '④は結論。「このように」でまとめ、「〜必要がある」と筆者の主張を述べている → 尾括型。', '問いかけ(①)と答え(④)を組にして短くまとめる。'], a: '人が使える水は限られているので、私たちは水を大切に使う必要がある。', check: 'まとめた文が、①の問いかけ(水は限りなくあるのか)への答えになっているかを確かめる。' }] },
      { h: '事実と意見を区別する', t: '説明的文章を正しく読むには、【事実】と【意見】を区別することが大切です。\n【事実】…実際にあったこと、調べれば確かめられること。例:「この町の人口は三万人だ。」\n【意見】…筆者が考えたこと、判断したこと。人によって考えが変わりうること。例:「この町はもっと人を呼ぶべきだ。」\n見分ける手がかりは、【文末】です。「〜べきだ」「〜と考える」「〜だろう」「〜ではないか」「〜が大切だ」などで終わる文は、意見であることが多いです。「〜である」「〜した」と言い切っていても、内容が調べて確かめられないものは意見です。\n筆者は、事実を根拠にして意見を述べます。「どの事実が、どの意見を支えているか」を考えながら読むと、文章の筋道が見えてきます。',
        key: '確かめられること=事実、筆者の考え・判断=意見。文末の「〜べきだ」「〜と考える」が手がかり。',
        ex: [{ q: '次の文は事実と意見のどちら?\nア 日本の国土のおよそ3分の2は森林である。\nイ 私たちは、もっと森林を大切にするべきだ。', hint: '文末と、調べて確かめられるかどうかに注目しよう。', steps: ['ア:国土にしめる森林の割合は、統計を調べれば確かめられる → 事実。', 'イ:文末が「〜べきだ」。筆者の考え・判断を述べている → 意見。', 'アの事実が、イの意見を支える根拠になっている関係も読み取れる。'], a: 'ア=事実、イ=意見', check: 'イは「そう思わない人」もいる内容で、アは人によって答えが変わらない内容であることを確かめる。' }] },
      { h: '小説・物語は「場面・心情・情景」を読む', t: '小説は、次の3点に注意して読みます。\n①【場面】…いつ・どこで・だれが。時間や場所が変わったところで場面が変わります。\n②【心情】…登場人物の気持ち。直接「悲しかった」と書かれていないことが多いので、【できごと → 行動・言葉・表情】から読み取ります。例:うつむいて返事をしない → 落ちこんでいる、気まずい。\n③【情景】…風景や天気の書き方。人物の気持ちと重ねて書かれることがあります。例:晴れわたった空 → 明るい気持ち。\n気持ちを答える問題では、「何があって(きっかけ)、どんな気持ちになり、どうしたか」の順で、本文の言葉を使って答えます。\nまた、物語の中で【気持ちが大きく変わるところ】は、いちばん大事な場面(山場)であることが多いので、変化の前と後をくらべて読みましょう。',
        key: '気持ちは「できごと(きっかけ)→ 気持ち → 行動」の真ん中にある。本文の行動や情景から読み取る。',
        ex: [{ q: '「リレーの選手に選ばれなかった。帰り道、健太は足元の小石を力いっぱいけとばした。空には重い雲がたれこめていた。」このときの健太の気持ちは?', hint: 'きっかけのできごと、行動、情景の3つを順に見よう。', steps: ['できごと(きっかけ):リレーの選手に選ばれなかった。', '行動:小石を力いっぱいけとばした → くやしさ・いらだちをぶつけている。', '情景:重い雲がたれこめている → 暗く沈んだ気持ちと重なっている。', '「きっかけ → 気持ち」の形でまとめる。'], a: 'リレーの選手に選ばれなかったことがくやしく、やり場のないいらだちと落ちこんだ気持ち。', check: '答えの気持ちが、本文の「けとばした」「重い雲」という表現と、どちらも矛盾しないか確かめる。' }] },
      { h: '意見文・感想文の書き方', t: '自分の考えを書く作文(意見文)は、次の型で書くと、読む人に伝わりやすくなります。\n①【主張】…問いに対する自分の考えを、最初にはっきり書く。\n②【理由】…なぜそう考えるのか。「なぜなら〜からだ」。\n③【具体例】…自分の体験や見聞きしたこと。理由を支える材料。\n④【反対意見への答え】…「たしかに〜という考えもある。しかし〜」。\n⑤【まとめ】…もう一度主張を書いてしめくくる。\n1つの段落には1つの内容だけを書き、段落の初めは1字下げます。\n【読書感想文】では、あらすじを長く書くのではなく、①心に残った場面、②なぜ心に残ったのか(自分の体験と結びつけて)、③読む前と後で自分の考えがどう変わったか、を中心に書きます。あらすじは、感想を伝えるのに必要な分だけで十分です。',
        key: '意見文は「主張 → 理由 → 具体例 → 反対意見への答え → まとめ」。主張は最初に書く。',
        ex: [{ q: '「中学生は毎日読書をするべきか」という題で意見文を書く。①主張の1文と、②理由の1文を書いてみよう。', hint: '賛成か反対か、立場を1つに決めてから書こう。', steps: ['まず立場を決める(ここでは賛成とする)。', '主張は、問いにそのまま答える形で、短く言い切る:「私は、中学生は毎日読書をするべきだと考える。」', '理由は「なぜなら〜からだ」の形で書く:「なぜなら、読書を続けると、知らない言葉や考え方に多く出会えるからだ。」', '理由は1つにしぼり、あとで具体例(体験など)で支えられるものにする。'], a: '(例)①私は、中学生は毎日読書をするべきだと考える。②なぜなら、読書を続けると、知らない言葉や考え方に多く出会えるからだ。', check: '主張の文だけを読んで、賛成か反対かがすぐに分かるか確かめる。' }] }
    ],
    faq: [['要旨と要約は、何がちがうの?', '要旨は「筆者がいちばん言いたいこと」で、1〜2文の短いものです。要約は「文章全体の内容を、順序にそって短くまとめたもの」で、具体例の要点などもふくみます。\n「要旨を答えなさい」と聞かれたら、具体例を入れずに主張だけを答えます。'], ['小説の気持ちの問題は、答えが人によってちがうのでは?', '自由に感想を書く問題ではなく、本文から読み取れる気持ちを答える問題なので、答えは本文の根拠で決まります。\n「どの行動・言葉・情景から、その気持ちが分かるか」を言えるかどうかを、自分で確かめましょう。'], ['意見文で、反対意見を書くと自分の意見が弱くならない?', '弱くはなりません。むしろ、反対意見を一度認めたうえで「それでも〜」と答えると、よく考えた意見だと伝わり、説得力が強くなります。\nただし、反対意見のほうを長く書きすぎないようにしましょう。']],
    terms: [['形式段落', '1字下げで始まる、見た目の段落'], ['意味段落', '内容のつながりでまとめた、大きな段落'], ['要旨', '筆者がいちばん言いたい中心の考え'], ['要約', '文章全体の内容を短くまとめたもの'], ['頭括型・尾括型・双括型', '主張が最初・最後・最初と最後の両方にある文章の型'], ['事実と意見', '確かめられることがらと、筆者の考え・判断'], ['情景', '人物の気持ちと重ねて描かれる、風景やようす']],
    miss: ['具体例の部分を要旨にふくめてしまう。「たとえば」以下は主張を支える材料だと考え、いったん外す。', '要旨と要約を同じものだと思い、文章全体を長々とまとめてしまう。要旨は主張だけを1〜2文で書く。', '小説の心情を、本文の根拠なしに自分の感想で答える。答えの根拠になる行動や情景に、必ず線を引いてから答える。', '意見文で、主張を最後まで書かない。最初の段落で立場をはっきり書く。'],
    sum: ['文章の種類を見きわめ、説明的文章は主張、文学的文章は気持ちの変化を探す。', '説明文は序論・本論・結論。主張の位置で頭括・尾括・双括型。', '要旨は、具体例を外し、問いかけと答えを組にしてまとめる。', '事実(確かめられる)と意見(筆者の判断)を区別する。', '小説は場面・心情・情景。気持ちは「できごと → 行動」から読む。', '意見文は主張 → 理由 → 具体例 → 反論への答え → まとめ。'],
    next: '次は「中学国語の総合」の単元で、これまで学んだ漢字・文法・敬語・古文・漢文・詩歌をまとめて復習しましょう。入試では、読解問題の中でこれらが組み合わせて問われます。'
  };

  // ===== 中学国語の総合 =====
  L.jx_jh2 = {
    goal: '高校入試で組み合わせて出る、漢字・文法・敬語・古文・漢文と故事成語・詩歌の要点を総復習し、入試問題の解き方の型を身につける。',
    intro: '高校入試の国語では、1つの文章の中で、敬語・古文・表現技法・故事成語などがまとめて問われます。どれも「覚えることが少なく、型どおりに解けば確実に点がとれる」分野です。この単元では、それぞれの要点を短く確認し、【問題を見たら最初に何をするか】という型を練習します。',
    pre: 'この単元は、中学国語の各単元(漢字・語彙、文法、敬語、古文、漢文、詩歌、読解)をひととおり学んだあとの【総復習】です。まだ学んでいない単元があれば、先にその単元を読んでおくと、ここでの説明がよく分かります。\n高校入試の国語は、多くの場合、①漢字の読み書き、②説明的文章(論説文・説明文)、③文学的文章(小説・随筆)、④古典(古文・漢文)、⑤作文、という大問で構成されています。都道府県や学校によって、形はちがいます。\n文法・敬語・表現技法などの知識問題は、独立した大問ではなく、読解の文章の中の小問として出ることが多いです。1問ごとの配点は小さくても、確実にとれるので合計すると大きな差になります。\nここで大切なのは、「知っているか」だけでなく、「問題を見て、すぐに正しい手順で解き始められるか」です。',
    secs: [
      { h: '入試国語の解き方:時間配分と順番', t: '入試では、すべての問題を同じペースで解いていると、最後の作文や長い読解で時間が足りなくなります。\nおすすめの順番は、①漢字・知識問題(短時間で確実に)→ ②古典(注と現代語訳を活用)→ ③読解(説明的文章・文学的文章)→ ④作文、です。ただし、作文の配点が大きい場合は、作文の時間を先に確保しておきます。\n大事なのは、【1問にこだわりすぎない】ことです。分からない問題には印をつけて先に進み、最後に戻ります。\n読解の記述問題は、本文の言葉を使って書けば部分点がもらえることが多いので、空らんのまま出さないようにしましょう。',
        key: '知識問題は短時間で確実に。分からない問題は印をつけて先へ進み、最後に戻る。' },
      { h: '漢字・語彙:意味と部首で書き分ける', t: '漢字の問題は、【読み】と【書き】の両方が出ます。書きの問題でまちがえやすいのは、同音異義語・同訓異字・送りがなです。\n書き分けの型:①その語の意味を考える → ②同じ字を使う別の熟語を思い出す → ③部首の意味が合っているか確かめる。\n例:「税金をオサめる」→ 税を納める(納税)、「学問をオサめる」→ 修める(修学)。\n語彙の問題では、ことわざ・慣用句・四字熟語の意味と、まちがいやすい言葉(役不足・気が置けない など)がよく出ます。\n送りがなは「形が変わる部分を送る」が基本です。「短い」「少ない」「動かす」など、よく出る語を確認しておきましょう。',
        key: '同じ読みの字は、意味を考え、同じ字を使う別の熟語で確かめる。',
        ex: [{ q: '「国をオサめる」「成功をオサめる」の「オサめる」を漢字にしよう。', hint: '「治める・収める・納める・修める」から、意味に合うものを選ぼう。', steps: ['「国をオサめる」は、国を支配して落ち着かせること → 「治める」(政治・統治の「治」)。', '「成功をオサめる」は、よい結果を手に入れること → 「収める」(収穫・収益の「収」)。', '「納める」(税)、「修める」(学問)は、どちらにも合わない。'], a: '国を治める/成功を収める', check: '「政治」「収穫」という熟語に置きかえて、それぞれの意味が合うか確かめる。' }] },
      { h: '文法:文節・品詞は手順どおりに', t: '文法の問題で多いのは、①文節の数・区切り、②文節どうしの関係(主語・述語、修飾・被修飾)、③品詞の識別、の3つです。\n【文節】…「ネ」を入れて区切る。文節の先頭には自立語がある。\n【修飾・被修飾】…2つの文節をつなげて読み、意味が通るかで確かめる。\n【品詞】…自立語か付属語か → 活用するか → 言い切りの形・働き、の順に調べる。\nよく出る識別:\n・「大きな」(連体詞)と「大きい」(形容詞)\n・「きれいだ」(形容動詞)と「学生だ」(名詞+助動詞)\n・「ある日」(連体詞)と「本がある」(動詞)\n選択肢から同じ品詞のものを選ぶ問題では、それぞれの語を、必ず同じ手順で調べてから比べます。',
        key: '品詞は「自立語か → 活用するか → 言い切り・働き」の順。同じ手順で選択肢を1つずつ調べる。',
        ex: [{ q: '「小さな花が、静かに咲いている。」の「小さな」と「静かに」の品詞を答えよう。', hint: 'それぞれ活用するかどうかを確かめよう。', steps: ['「小さな」:「小さだ」「小さなかった」とは言えず、形が変わらない → 活用しない自立語。', '名詞「花」だけをくわしくしているので、連体詞。', '「静かに」:言い切りの形にすると「静かだ」。「静かな・静かだった」と活用する。', '「だ」で終わる用言なので、形容動詞。'], a: '小さな=連体詞、静かに=形容動詞', check: '「小さい」なら「小さかった」と活用する形容詞になる。形の似た語と比べて、活用の有無でちがいを確かめる。' }] },
      { h: '敬語:最初に主語を決める', t: '解き方の型:①その動作をするのはだれか(主語)を決める → ②目上の人なら尊敬語、自分・身内なら謙譲語 → ③特別な形があればそれを使う。\n特によく出る組み合わせ:\n言う … おっしゃる/申す・申し上げる\n行く・来る … いらっしゃる/参る(行く は うかがう も)\n見る … ご覧になる/拝見する\n食べる … 召し上がる/いただく\nする … なさる/いたす\n入試では、「まちがった敬語を選ぶ」「適切な敬語に直す」問題がよく出ます。まちがいの多くは、【相手の動作に謙譲語を使っている】ものです。',
        key: '敬語は「主語 → 尊敬か謙譲か → 特別な形」の順で決める。',
        ex: [{ q: '「(生徒が先生に)先生、この本はもう拝見しましたか。」この文の敬語のまちがいを直そう。', hint: '「見る」のはだれかを確かめよう。', steps: ['「見る」のはだれか → 先生(目上の人)。', '目上の人の動作には尊敬語を使う。「拝見する」は謙譲語なのでまちがい。', '「見る」の尊敬語は「ご覧になる」。丁寧語「ます」とあわせて「ご覧になりましたか」。'], a: '先生、この本はもうご覧になりましたか。', check: '「拝見する」は「私が拝見します」のように自分の動作に使う言葉であることを確かめる。' }] },
      { h: '古文:仮名遣いと係り結びは「見たら即反応」', t: '入試古文の小問は、次の3つがほとんどです。\n①【歴史的仮名遣い】…語の頭以外の「は・ひ・ふ・へ・ほ」→「わ・い・う・え・お」、「ゐ・ゑ・を」→「い・え・お」、「あう・いう・えう」→「おう・ゆう・よう」。\n②【係り結び】…ぞ・なむ・や・か → 文末は連体形、こそ → 已然形。\n③【主語の把握】…「〜て」でつながっている間は、主語はふつう同じ。会話の「 」の前後や、「〜ば」「〜に」「〜を」のあとで主語が変わることがある。\n本文の内容は、たいてい現代語訳や注釈が手がかりになります。注は必ず読みます。\n「ひらがなで書きなさい」という仮名遣いの問題では、【答えは必ず現代仮名遣いのひらがな】で書きます。漢字まじりで書いたり、歴史的仮名遣いのまま書いたりしないように注意します。',
        key: '古文の小問は、仮名遣い・係り結び・主語の3つ。注は必ず読む。',
        ex: [{ q: '作例「これをこそ、まことの道とはいひ( )。」の( )に、過去の助動詞「けり」を正しい形にして入れよう。', hint: '文の中の係りの助詞を探そう。', steps: ['文の中に係りの助詞を探す →「こそ」がある。', '「こそ」の結びは已然形。', '「けり」の已然形は「けれ」。'], a: 'けれ(「まことの道とはいひけれ」)', check: 'もし係りの助詞が「なむ」なら連体形「ける」になることと比べ、「こそ」だけが已然形になることを確かめる。' }] },
      { h: '漢文と故事成語', t: '【漢文】…レ点はすぐ下の1字から返る、一・二点は一の字まで読んでから二へ返る。書き下し文では助詞・助動詞にあたる字(不・之・也など)はひらがなに、置き字(而・於など)は書かない。\n【返り点をつける問題】…書き下し文の順番に合わせて、漢字に番号を振ります。番号が1つ前にもどるところにレ点、2字以上もどるところに一・二点をつけます。\n【故事成語】…矛盾(つじつまが合わない)、推敲(文章を練り直す)、蛇足(よけいなもの)、五十歩百歩(大差ない)、漁夫の利(第三者が得をする)。\n故事成語の問題は、もとの話を読ませたうえで、「この話からできた言葉は?」「その意味は?」と問う形が多いです。話の筋(だれが、何をして、どうなったか)をつかめば答えられます。',
        key: '返り点は、書き下し文の順に番号を振り、1字もどるならレ点、2字以上もどるなら一・二点。',
        ex: [{ q: '「書を読む」と読めるように、白文「読書」に返り点をつけよう。また、「高山に登る」と読めるように「登高山」に返り点をつけよう。', hint: '書き下し文の順番に、漢字に番号を振ろう。', steps: ['「書を読む」:読む順は 書(1)→ 読(2)。「読」は1字下の「書」から1字もどって読む → 「読」にレ点。→ 読レ書', '「高山に登る」:読む順は 高(1)→ 山(2)→ 登(3)。「登」は「山」から2字もどる → 一・二点を使う。', '先に読む「山」に一点、あとで返る「登」に二点をつける。→ 登二高山一'], a: '読レ書/登二高山一', check: 'つけた返り点のとおりに読み直し、書き下し文と同じ順番になるか確かめる。' },
          { q: '「彼の説明は、前に言ったことと後で言ったことが食いちがっていて、( )している。」( )に入る故事成語は?', hint: '「つじつまが合わない」という意味の故事成語は?', steps: ['「前と後で言うことが食いちがう」=つじつまが合わない、という意味。', 'つじつまが合わないことを表す故事成語を思い出す。', 'どんな盾も突き通す矛と、どんな矛も防ぐ盾の話 → 矛盾。'], a: '矛盾', check: '矛と盾の話で、売り手の言葉が前後でかみ合わなかったことと、問題文の状況が同じか確かめる。' }] },
      { h: '詩歌の表現技法', t: '【表現技法】…直喩(ようだ)、隠喩(ようだ なしのたとえ)、擬人法、倒置法、体言止め、反復、対句。名前と効果をセットで答えます。\n【短歌】…五・七・五・七・七。句切れは「。」を打てる意味の切れ目。\n【俳句】…五・七・五。季語は旧暦で考える(五月雨=夏、天の川=秋)。切れ字(や・かな・けり)に感動の中心がある。\n入試でよく出る問いの形:\n・「この詩に使われている表現技法を選べ」→ 該当する行を見つけ、名前を確かめる。\n・「この表現の効果を説明せよ」→「〜を強調している」「〜という余韻を残している」「〜を生き生きと表している」のように、【何を・どうしているか】を書く。\n・「季語と季節を答えよ」→ 季語を探し、旧暦で季節を決める。',
        key: '表現技法は名前と効果をセットで。季語は旧暦で考える。' }
    ],
    faq: [['知識問題と読解問題、どちらを先に勉強すればいい?', '短期間で点数を上げやすいのは知識問題(漢字・文法・敬語・古典の基本)です。覚えれば確実に点になるからです。\nただし、読解力は時間をかけて伸びるものなので、知識問題と並行して、毎日少しずつ文章を読む練習も続けましょう。'], ['古文や漢文の本文が全然読めなくても、点はとれる?', 'とれます。入試の古典では、注や現代語訳がついていることが多く、仮名遣い・係り結び・返り点などの小問は、本文の意味が分からなくても解けるものがあります。\nまずは、確実にとれる小問を落とさないことを目標にしましょう。'], ['記述問題は、どこまで書けば点がもらえるの?', '多くの場合、答えに入れるべき要素(キーワード)がいくつか決まっていて、入っている数に応じて点がもらえます。\n本文の言葉を使い、「〜から。」「〜こと。」など、問いに合った文末で書くことを心がけましょう。']],
    terms: [['同訓異字', '訓読みが同じで、意味がちがう漢字(治める・収める など)'], ['品詞の識別', '形の似た語の品詞を見分けること'], ['尊敬語', '目上の人の動作を高める敬語'], ['謙譲語', '自分側の動作をへりくだる敬語'], ['係り結び', 'ぞ・なむ・や・か → 連体形、こそ → 已然形で結ぶきまり'], ['書き下し文', '漢文を日本語の文に直したもの'], ['季語', '俳句で季節を表す言葉(旧暦で考える)']],
    miss: ['敬語の問題で、主語を確かめずに語感で選ぶ。動詞を見たら、まず「だれの動作か」に線を引く。', '係り結びの「こそ」を連体形で結んでしまう。「こそ」だけは已然形と、別にして覚える。', '故事成語を、もとの話を知らずに字面で意味を想像してしまう(蛇足=蛇の足、ではなく「よけいなもの」)。話の筋とセットで覚える。', '仮名遣いの問題で、答えを歴史的仮名遣いのまま書く。「現代仮名遣いで」という指示を丸で囲んでから答える。'],
    sum: ['入試は時間配分が大切。知識問題を短時間で確実にとる。', '漢字の書き分けは、意味と、同じ字を使う別の熟語で確かめる。', '品詞は「自立語か → 活用するか → 言い切り・働き」の順。', '敬語は「主語 → 尊敬か謙譲か → 特別な形」の順で決める。', '古文の小問は、仮名遣い・係り結び・主語の3つが中心。注は必ず読む。', '漢文は返り点の順番、故事成語はもとの話、表現技法は名前と効果をセットで。'],
    next: '次は「難関レベル:中学国語」の単元に進みましょう。ここで確認した基本の型をもとに、二重敬語・識別問題・漢文の句形など、難関校で差がつくところを学びます。'
  };

  L.jx_jh3 = {
    goal: '難関高校の入試で問われる、敬語の細かな使い分け・まちがえやすい四字熟語や慣用句・語の識別・漢文の句形・記述問題まで、根拠をもって正確に答えられるようになる。',
    intro: '難関校の国語では、「なんとなく正しそう」では答えられない問題が出ます。敬語なら二重敬語や身内敬語、四字熟語なら1字のちがい、文法なら同じ形の語の識別、漢文なら再読文字のような特別な読み方まで問われます。どの問題も、【ルールに当てはめて理由を言える】ことが正解への近道です。',
    pre: 'この単元は、「中学国語の総合」で学ぶ基本(敬語の3種類、品詞の見分け方、返り点、係り結び など)が分かっていることを前提にしています。不安な人は、先に各単元を読み直しましょう。\n特に、次の3つは必ず思い出しておきます。①尊敬語は目上の人の動作、謙譲語は自分側の動作に使う。②品詞は「自立語か付属語か → 活用するか → 働き」で見分ける。③漢文では、返り点のある字は飛ばして後で読む。\n難関校の問題でよく使う考え方に、【置きかえテスト】があります。ある語を別の語に置きかえてみて、意味が通るかどうかで、語の種類や意味を判断する方法です。たとえば「ない」を「ぬ」に置きかえられるか、を試します。\nこの単元では、この置きかえテストを何度も使います。「なぜその答えになるのか」を、置きかえの結果で説明できるようにしましょう。',
    secs: [
      { h: '敬語の使い分け(上級)', t: '①【主語を確認する】…尊敬語は目上の人の動作、謙譲語は自分側の動作。\n例:先生が来る → いらっしゃる・お見えになる・お越しになる・おいでになる/私が(先生の家に)行く → うかがう・参る\n②【二重敬語を避ける】…1つの語に同じ種類の敬語を重ねない。\n× おっしゃられる(おっしゃる+られる)、ご覧になられる(ご覧になる+られる)\n③【身内敬語を避ける】…ソトの人に対して、自分の家族や自分の会社の人を高めない。\n× (他社の人に)部長はただいま外出していらっしゃいます → ○ (部長の)〇〇はただいま外出しております\n④【「お〜する」は謙譲語】…相手の動作には使えない。\n× どうぞお座りしてください → ○ どうぞお座りください(おかけください)\n⑤【「〜させていただく」の使いすぎ】…相手の許可を得て行い、それで自分が恩恵を受ける場合に使う言い方です。許可と関係ない場面で使うと、まわりくどく感じられます。',
        key: '主語の確認 → 二重敬語・身内敬語・「お〜する」の誤用がないか、の順で点検する。',
        ex: [{ q: '次のうち、敬語の使い方が正しいものはどれ?\nア 先生が、そうおっしゃられました。\nイ (電話で客に)父はただいま外出しております。\nウ 先生が私の家に参られました。', hint: '1つずつ、主語と敬語の種類を確かめよう。', steps: ['ア:「おっしゃる」(尊敬語)に「られる」(尊敬)を重ねた二重敬語 → ×。正しくは「おっしゃいました」。', 'イ:父(身内)のことをソトの人に話している。「おる」は自分側をへりくだる言い方で、身内を高めていない → ○。', 'ウ:先生の動作に謙譲語「参る」を使っている → ×。正しくは「いらっしゃいました」。'], a: 'イ', check: 'アとウを正しく直した文(おっしゃいました/いらっしゃいました)と比べ、どこがまちがいだったかを言えるか確かめる。' }] },
      { h: 'まちがえやすい四字熟語・慣用句', t: '1字のまちがいがよく問われます。漢字の意味から理由をつけて覚えます。\n【危機一髪】…髪の毛1本ほどの差で危機が迫る。(×一発)\n【五里霧中】…五里四方に立ちこめる霧の中 → 方針が立たず迷う。(×夢中)\n【絶体絶命】…体も命も窮まる → 追いつめられてどうにもならない。(×絶対)\n【単刀直入】…1本の刀で敵陣に切りこむ → 前置きなく本題に入る。(×短刀)\n【言語道断】…言葉で言い表せないほどひどい。(×言語同断)\n慣用句は、誤用されやすい形に注意します。\n【的を射る】…要点を正しくとらえる(「的を得る」は誤りとされることが多い)。\n【汚名をすすぐ・汚名を返上する】(×汚名挽回。挽回するのは「名誉」)\n【采配を振る】…指図する。\n【気が置けない】…遠慮しなくてよい。',
        key: '四字熟語は、1字ずつの意味から理由をつけて覚える。理由が言えれば書きまちがえない。',
        ex: [{ q: '「ゴリムチュウ」「ゼッタイゼツメイ」を正しい漢字で書こう。', hint: '「何の中にいるのか」「何が窮まるのか」を考えよう。', steps: ['ゴリムチュウ:五里四方に立ちこめる「霧」の中で、方向が分からないという意味 → 五里霧中(夢中ではない)。', 'ゼッタイゼツメイ:「体」も「命」も窮まる(きわまる)という意味 → 絶体絶命(絶対ではない)。', '「夢中」「絶対」はよく見る熟語なので、つい書いてしまう。意味から理由をつけて書き分ける。'], a: '五里霧中/絶体絶命', check: '「霧の中で迷う」「体と命が窮まる」と、字の意味で四字熟語全体の意味を説明できるか確かめる。' }] },
      { h: '語の識別1:「ない」', t: '同じ形でも品詞や意味がちがう語を見分けることを【識別】といいます。難関校では「ない」の識別がよく出ます。\n①【助動詞の「ない」】…動詞などについて打ち消す。「ぬ」に置きかえられる。例:本を読まない → 読まぬ(○)\n②【形容詞の「ない」】…それだけで「存在しない」という意味を表す自立語。「ぬ」に置きかえられない。例:お金がない → お金がぬ(×)\n③【補助形容詞の「ない」】…形容詞・形容動詞などのあとについて打ち消す。前に「は」「も」を入れられる。例:寒くない → 寒くはない(○)\n④【形容詞の一部】…1語の中にふくまれている「ない」。切りはなせない。例:少ない、危ない、きたない\n見分けの順番:まず「ぬ」に置きかえる(○なら助動詞)→ 次に前に「は」を入れる(○なら補助形容詞)→ 残りは、それだけで意味があれば形容詞、語の一部なら形容詞の一部、と判断します。',
        key: '「ぬ」に置きかえられれば助動詞、前に「は」を入れられれば補助形容詞。',
        ex: [{ q: '次の「ない」のうち、助動詞はどれ?\nア 今日は雨が降らない。\nイ 部屋が静かではない。\nウ 机の上に何もない。', hint: '1つずつ「ぬ」に置きかえてみよう。', steps: ['ア:「降らぬ」と置きかえられる → 助動詞。', 'イ:「静かではぬ」とは言えない。前に「は」がすでに入っている(静かではない)→ 補助形容詞。', 'ウ:「何もぬ」とは言えない。それだけで「存在しない」意味を表す → 形容詞。'], a: 'ア', check: 'アの「降ら」は動詞「降る」の形が変わったもので、動詞についた「ない」が助動詞になることを確かめる。' }] },
      { h: '語の識別2:「れる・られる」と「の」', t: '【「れる・られる」の4つの意味】\n①【受身】…ほかから動作を受ける。「〜される」。例:弟が母にしかられる。\n②【可能】…「〜できる」。例:朝五時に起きられる。\n③【自発】…自然にそうなる。「思う・案じる・しのぶ」など心の動きを表す語につくことが多い。例:故郷のことが思い出される。\n④【尊敬】…目上の人の動作を高める。例:先生が話される。\n見分け方:「〜できる」に置きかえられれば可能、「自然と〜」を補えれば自発、主語が目上で「お〜になる」に置きかえられれば尊敬、「〜に」(動作をする相手)があれば受身のことが多い。\n【「の」の識別】\n①【主語を表す】…「が」に置きかえられる。例:私の書いた本 → 私が書いた本\n②【連体修飾】…「〜の+名詞」で名詞をくわしくする。例:私の本\n③【体言の代用】…「こと・もの」に置きかえられる。例:走るのが好きだ → 走ることが好きだ\n④【並立】…「〜の〜の」と並べる。例:行くの行かないのと迷う',
        key: '「れる・られる」も「の」も、置きかえテスト(できる/お〜になる/が/こと)で意味を決める。',
        ex: [{ q: '「校長先生が、朝礼で話される。」と「朝五時なら起きられる。」の「れる・られる」の意味をそれぞれ答えよう。', hint: '「お〜になる」「〜できる」に置きかえてみよう。', steps: ['1つ目:主語は校長先生(目上)。「お話しになる」に置きかえても意味が変わらない → 尊敬。', '2つ目:「起きることができる」に置きかえられる → 可能。', 'どちらも「〜に(動作をする相手)」がないので受身ではなく、心の動きの語でもないので自発でもない。'], a: '話される=尊敬、起きられる=可能', check: '置きかえた文(お話しになる/起きることができる)を読み、もとの文と同じ意味になるか確かめる。' }] },
      { h: '漢文の句形', t: '難関校では、返り点に加えて、決まった読み方をする句形が出ます。\n【再読文字】…1字を2回読む字。1回目は返り点を無視して副詞として読み、2回目は返り点に従って助動詞(など)として読む。\n・未 → いまだ〜ず(まだ〜しない)\n・将・且 → まさに〜んとす(今にも〜しようとする)\n・当 → まさに〜べし(当然〜すべきだ)\n書き下し文では、1回目の読みは漢字(未だ)、2回目の読みはひらがな(ず)で書きます。\n【否定】不(〜ず)、無(〜なし)、非(〜にあらず)\n【反語】…「豈〜哉」(あに〜んや)=どうして〜だろうか、いや〜ない。疑問の形で、強く打ち消す。\n【詠嘆】…「不亦〜乎」(また〜ずや)=なんと〜ではないか。『論語』の「亦説ばしからずや」がこの形です。',
        key: '再読文字は、1回目=返り点を無視して副詞として読む、2回目=返り点に従って読む。',
        ex: [{ q: '「未 レ 知」(未は再読文字)を書き下し、意味を答えよう。', hint: '「未」は「いまだ〜ず」と2回読む。', steps: ['「未」は再読文字。1回目は返り点を無視して「いまだ」と読む。', 'レ点に従って「知」を読む →「知ら」。', '2回目は「未」に返って「ず」と読む(書き下し文ではひらがな)。', 'つなげて「未だ知らず」。'], a: '未だ知らず(まだ知らない)', check: '書き下し文で、1回目の「未だ」は漢字、2回目の「ず」はひらがなになっているかを確かめる。' }] },
      { h: '記述問題の書き方', t: '難関校では、記述問題の配点が大きくなります。記述は、次の手順で書きます。\n①【問いの形を確かめる】…「なぜか」なら文末は「〜から。」、「どういうことか」なら「〜こと。」、「どんな気持ちか」なら「〜気持ち。」。\n②【本文から材料を集める】…傍線部の前後を読み、答えに必要な部分に線を引く。\n③【材料をつなぐ】…「AなのでB」「AだがB」のように、材料どうしの関係が分かる形でまとめる。\n④【字数を調整する】…指定字数の8割以上を目安に書く。具体例は省き、まとめた言い方を使う。\n小説の気持ちの記述では、「きっかけ(できごと)+気持ち」の2つを入れると、要素が足りなくなりにくいです。\n書いたら、問いの文と答えを続けて読み、【問いと答えがかみ合っているか】を必ず確かめます。',
        key: '記述は「問いの形 → 本文の材料 → つなぐ → 字数調整」。文末を問いに合わせる。',
        ex: [{ q: '「リレーの選手に選ばれなかった。帰り道、健太は足元の小石を力いっぱいけとばした。」について、「健太が小石をけとばしたのはなぜか」という問いに、30字以内で答えよう。', hint: '「なぜか」と聞かれているので、文末は「〜から。」にしよう。', steps: ['問いの形:「なぜか」→ 文末は「〜から。」。', '材料を集める:きっかけ=リレーの選手に選ばれなかった。気持ち=くやしさ・いらだち。', 'つなぐ:「選ばれなかった」ことが原因で「くやしい」気持ちになり、それを小石にぶつけた、という関係にする。', '字数を確かめてまとめる。'], a: '(例)リレーの選手に選ばれなかったくやしさをぶつけたかったから。(29字)', check: '問いの文に続けて「健太が小石をけとばしたのは、〜から。」と読み、かみ合っているか、字数が30字以内か確かめる。' }] }
    ],
    faq: [['識別の問題は、全部覚えないと解けないの?', '覚えることは多くありません。大事なのは、置きかえテストのやり方です。\n「ない」なら「ぬ」、「の」なら「が」や「こと」、「れる・られる」なら「できる」「お〜になる」と、試す言葉さえ覚えておけば、あとはその場で判断できます。'], ['「的を得る」は本当にまちがいなの?', '昔から「的を射る」が正しいとされてきました。「当を得る」(道理にかなう)と混ざった言い方だと考えられているからです。\n近年は「的を得る」も認める辞書がありますが、入試では「的を射る」を正しいとするのが安全です。'], ['記述問題で、自分の言葉で書いたほうがいいの?', '基本は、本文の言葉を使って書くほうが安全です。本文の言葉は、採点の基準になるキーワードであることが多いからです。\nただし、比喩や具体例のまま書くと意味が伝わらないので、その部分は分かりやすい言葉に言いかえます。']],
    terms: [['二重敬語', '同じ種類の敬語を重ねた誤った言い方'], ['身内敬語', 'ソトの人に対して身内を高めてしまう誤った使い方'], ['識別', '形が同じ語の品詞や意味を見分けること'], ['補助形容詞', 'ほかの語のあとについて、打ち消しなどの意味をそえる形容詞(寒くない の「ない」)'], ['自発', '「自然に〜される」という意味(思い出される など)'], ['再読文字', '1字を2回読む漢字(未・将・当 など)'], ['反語', '疑問の形で強く打ち消す表現(〜だろうか、いや〜ない)'], ['詠嘆', '感動を表す表現']],
    miss: ['「おる」「参る」を、相手の動作に使ってしまう。謙譲語の一覧を見直し、相手の動作には使わないと確認する。', '「絶体絶命」を「絶対絶命」、「五里霧中」を「五里夢中」と書く。見なれた熟語に引きずられないよう、字の意味で理由をつける。', '「ない」の識別で、すべて「ぬ」に置きかえて終わりにする。助動詞以外の3種類も、「は」を入れる・単独で意味があるか、の順で確かめる。', '再読文字の2回目の読み(ず・べし など)を書き下し文で漢字のまま書く。2回目はひらがな、と決めておく。', '記述の文末が問いに合っていない(「なぜか」に「〜こと。」で答える)。書き終えたら問いと続けて読む。'],
    sum: ['敬語は主語を確かめ、二重敬語・身内敬語・「お〜する」の誤用に注意する。', '四字熟語は漢字の意味から理由をつけて覚える。', '「ない」は「ぬ」に置きかえて助動詞、「は」を入れて補助形容詞を見分ける。', '「れる・られる」は受身・可能・自発・尊敬。置きかえテストで決める。', '再読文字は「1回目=副詞、2回目=返り点に従って読む」。「豈〜哉」は反語、「不亦〜乎」は詠嘆。', '記述は文末を問いに合わせ、本文の材料をつないで書く。'],
    next: '高校に進んだら「古文単語」と「古典文法」の単元に進みましょう。中学で学んだ仮名遣い・係り結び・敬語の知識をもとに、古文を自分の力で訳せるようになります。'
  };

  // ===== 古文単語 =====
  L.j_kogo = {
    goal: '現代語と意味がちがう古文単語と、古文にしかない重要単語の意味を覚え、形が変わった単語や呼応の副詞も見分けて、文脈に合わせて訳せるようになる。',
    intro: '古文単語は、英単語と同じく、読むための【いちばんの土台】です。古文には、「をかし」のように今も似た形で使うのに意味がちがう語と、「つとめて」のように今は使わない語があります。とくに前者は、今の意味で読むと話の筋をまちがえるので、最優先で覚えます。',
    pre: '古文を読むときに必要な力は、大きく分けて3つあります。①歴史的仮名遣いを読む力、②古文単語の意味を知っている力、③古典文法(助動詞など)の知識です。この単元は②にあたります。\n歴史的仮名遣いの基本をおさらいしておきましょう。語の頭以外の「は・ひ・ふ・へ・ほ」は「わ・い・う・え・お」と読み、「ゐ・ゑ・を」は「い・え・お」と読みます。例:いふ → いう、をかし → おかし。\n古文の単語は、今の言葉と同じように、後ろにつく言葉によって形が変わります(活用)。たとえば「うつくし」は、「うつくしく」「うつくしき」などの形になります。辞書や単語帳には、言い切りの形(終止形)でのっています。\n単語帳では、1つの単語に意味がいくつも書かれていることがあります。最初は、いちばん上(代表的な意味)と、【その語の中心のイメージ】を覚えることから始めましょう。',
    secs: [
      { h: '古文単語は2つのグループで覚える', t: '古文単語は、次の2つのグループに分けると、覚える順番が分かります。\n【グループ1:今もある言葉で、意味がちがうもの】…をかし、あはれなり、うつくし、ありがたし、やがて など。\n見た目が今の言葉と似ているので、意味を知らないと、今の意味でまちがって読んでしまいます。だから【最優先】で覚えます。\n【グループ2:今は使わない言葉】…いと、つとめて、ゆかし、いみじ など。\n見なれない言葉なので、「知らない」と気づくことはできます。よく出るものから順に覚えます。\n覚えるときのコツは、【語源(言葉のなりたち)】を考えることです。「ありがたし」は「有り+難し」=「あることが難しい」→「めったにない」。語源が分かると、意味を忘れにくくなります。',
        key: '今もある言葉で意味がちがう語(をかし・やがて など)を最優先で覚える。語源を考えると忘れにくい。' },
      { h: '現代語と意味がちがう単語(最優先)', t: '【をかし】…趣がある・美しい・かわいらしい・おもしろい。(今の「おかしい=変だ」ではない)\n【あはれなり】…しみじみとした趣がある・しみじみと心を動かされる。(「かわいそう」だけではない)\n【うつくし】…かわいらしい。(今の「美しい」よりも、小さいものへの愛らしさ)\n【ありがたし】…めったにない・(めったにないほど)すばらしい。(「有り+難し」=あることが難しい)\n【やがて】…そのまま・すぐに。(今の「そのうちに」ではない)\n【おどろく】…はっと気づく・目を覚ます。\n【ののしる】…大声で騒ぐ・評判になる。(悪口を言う、ではない)\n【あやし】…不思議だ・身分が低い・粗末だ。\n【めでたし】…すばらしい・りっぱだ。\n【かなし】…いとしい・かわいい(悲しい の意味もある)。\n【にほふ】…美しく照りかがやく(色の美しさ)。(においだけではない)\n「をかし」と「あはれなり」は、平安時代の文学を代表する美意識を表す言葉です。「をかし」は明るく知的な感動、「あはれなり」はしみじみとした感動、と区別すると分かりやすくなります。',
        key: '今と同じ形でも意味がちがう。をかし=趣がある、うつくし=かわいらしい、やがて=そのまま・すぐに。',
        ex: [{ q: '『竹取物語』の一節「三寸ばかりなる人、いとうつくしうてゐたり。」を現代語訳しよう。', hint: '「うつくし」は今の「美しい」とは少し意味がちがう。', steps: ['「三寸ばかりなる人」=三寸(約9cm)ほどの人。', '「いと」=とても。「うつくしう」=「うつくし」(かわいらしい)の形が変わったもの。', '「ゐたり」=座っていた(「ゐる」は座る・じっとしている)。', 'つなげて訳す。小さな子へのいとおしさなので、「美しい」と訳すより「かわいらしい」が正確。'], a: '三寸ほどの人が、とてもかわいらしい様子で座っていた。', check: '竹の中から見つかった小さな女の子の場面なので、「かわいらしい」という訳が場面に合っているか確かめる。' }] },
      { h: '古文にしかない重要単語', t: '【いと】…とても・たいそう。(「いと〜ず」なら「たいして〜ない」)\n【いみじ】…程度がはなはだしい。よい意味(すばらしい)にも悪い意味(ひどい)にもなる。\n【つとめて】…早朝・(何かがあった)翌朝。\n【ゆかし】…見たい・聞きたい・知りたい(心がひかれる)。\n【つれづれなり】…することがなく退屈だ・手持ちぶさただ。\n【あさまし】…驚きあきれるほどだ。\n【さうざうし】…物足りない・さびしい。\n【年ごろ】…長年・数年来。(今の「年ごろ=適齢期」ではない)\n【なかなか】…かえって・中途半端に。\n【ながむ】…物思いにふけってぼんやり見る。\n人を表す言葉も覚えておくと、登場人物がつかみやすくなります。【翁】(おきな)=おじいさん、【嫗】(おうな)=おばあさん、【帝・御門】(みかど)=天皇、【女房】=宮中などに仕える女性。',
        key: 'いと=とても、いみじ=程度がすごい(よくも悪くも)、つとめて=早朝、ゆかし=見たい・知りたい。',
        ex: [{ q: '『枕草子』の「冬はつとめて。」の意味は?', hint: '「春はあけぼの」と同じ形の文だよ。', steps: ['「つとめて」=早朝。', '直前の「春はあけぼの」と同じ形で、季節ごとに趣のある時間帯を挙げている。', '「をかし」などの言葉が省略されていると考えて補う。'], a: '冬は早朝(が趣がある)。', check: '春=あけぼの(明け方)、夏=夜、秋=夕暮れ、と同じく「時間帯」を挙げる形になっているか確かめる。' }] },
      { h: '形が変わった単語を見ぬく', t: '古文の単語は、文の中では形が変わって出てくることが多いです。そのまま単語帳を引いても見つからないので、【言い切りの形(終止形)】にもどしてから意味を考えます。\n①【活用による変化】…後ろにつく言葉で形が変わる。\n例:うつくし → うつくしき(人)、うつくしく(て)\n例:ゆかし → ゆかしけれ、ゆかしく\n②【音便】…発音しやすいように、音が変わったもの。\n例:うつくしく → うつくしう(「く」が「う」に変わるウ音便)\n例:いみじく → いみじう\nつまり、「〜しう」という形を見たら、「〜しく」の音便ではないかと考え、「〜し」にもどして意味を調べます。\n③【歴史的仮名遣い】…「をかし」は読みは「おかし」ですが、辞書では「をかし」の形でのっています。古語辞典を引くときは、歴史的仮名遣いのまま引きます。',
        key: '形が変わった語は、言い切りの形(〜し など)にもどしてから意味を考える。「〜しう」は「〜しく」の音便。',
        ex: [{ q: '作例「いみじう泣く」の「いみじう」の言い切りの形と、ここでの意味を答えよう。', hint: '「〜じう」は「〜じく」の音便だよ。', steps: ['「いみじう」は「いみじく」がウ音便で変わった形。言い切りの形は「いみじ」。', '「いみじ」の中心の意味は「程度がはなはだしい」。', '泣く場面なので、悪い・強い方向の意味で訳す →「ひどく・激しく」。'], a: '言い切りの形=いみじ、意味=ひどく(激しく)泣く', check: '「すばらしく泣く」と訳すと場面に合わないことを確かめ、文脈から意味の方向を決めたか見直す。' }] },
      { h: '呼応の副詞:セットで意味が決まる', t: '古文には、決まった言葉と【セットで使われて】特別な意味になる副詞があります。これを【呼応の副詞】といいます。前の副詞を見たら、後ろにセットの言葉がないか探します。\n【え〜ず】…〜できない(不可能)。例:え言はず=言うことができない\n【な〜そ】…〜するな(禁止)。例:な泣きそ=泣くな\n【つゆ〜ず】…少しも〜ない。\n【さらに〜ず】…まったく〜ない。\n【をさをさ〜ず】…ほとんど〜ない。\n【よも〜じ】…まさか〜ないだろう。\n【いかで〜む】…どうにかして〜たい・〜よう。\nなぜセットで覚えるのでしょうか。「え」や「な」は1字だけなので、見落としやすく、意味も単独では分かりにくいからです。後ろの「ず」「そ」と組にして初めて、意味がはっきりします。',
        key: 'え〜ず=〜できない、な〜そ=〜するな、つゆ〜ず=少しも〜ない。前の副詞と後ろの言葉をセットで見る。',
        ex: [{ q: '作例「問はれて、え答へず。」を現代語訳しよう。', hint: '「え」と「ず」のセットに注目しよう。', steps: ['「問はれて」=質問されて(「る」は受身)。', '「え〜ず」は不可能を表す呼応の副詞のセット。', '「え答へず」=答えることができない。'], a: '質問されて、答えることができない。', check: '「え」を取って「答へず」だけにすると「答えない」になり、「できない」の意味が消えることを比べて確かめる。' },
          { q: '作例「な泣きそ。」を現代語訳しよう。', hint: '「な〜そ」は禁止を表すセット。', steps: ['「な」と、文末の「そ」がセットになっている → 禁止「〜するな」。', 'はさまれた「泣き」は「泣く」の形が変わったもの。', 'つなげて「泣くな」。やわらかく「泣かないでくれ」と訳してもよい。'], a: '泣くな(泣かないでおくれ)。', check: '「泣く」+禁止という組み合わせになっているかを確かめる。' }] },
      { h: '意味の決め方:文脈で選ぶ', t: '古文単語には意味がいくつもあるものが多いので、【文脈で1つに決める】必要があります。\n①その語の意味の候補を思い出す。\n②前後の内容がよいことか悪いことかを確かめる。\n③候補を当てはめて、話の流れが自然になるものを選ぶ。\n例:「いみじう泣く」→ 泣く場面なので悪い・強い意味 →「ひどく泣く・激しく泣く」。\n「いみじき絵師」→ ほめている場面 →「すばらしい絵師」。\n覚えるときは、1つの単語につき【中心の意味(イメージ)】をつかんでおくと、場面に応じて訳し分けられます。「いみじ」なら「ふつうではない、程度がすごい」が中心です。「あやし」なら「ふつうとちがう」が中心で、そこから「不思議だ」「身分が低い(貴族から見てふつうでない)」「粗末だ」が生まれています。',
        key: '意味が複数ある語は、中心のイメージをつかみ、前後の内容(よい・悪い)から1つに決める。',
        ex: [{ q: '作例「月の明かき夜、やがて寝もせで眺めけり。」の「やがて」の意味として正しいのは?(ア そのうちに イ そのまま)', hint: '「やがて」は、今とは意味がちがう単語だったね。', steps: ['「やがて」は古文では「そのまま・すぐに」の意味。', '今の「そのうちに」の意味ではない。', '当てはめると「月の明るい夜、そのまま寝もしないで(月を)眺めた」と自然につながる。'], a: 'イ そのまま', check: 'アを当てはめた「そのうちに寝もしないで」は、意味がつながらないことを確かめる。' }] }
    ],
    faq: [['古文単語は、いくつくらい覚えればいいの?', '高校の定期テストや共通テストの基本では、まず300語前後を目安にする単語帳が多いです。\n最初から全部を覚えようとせず、この単元にある「今と意味がちがう語」と「古文にしかない重要語」から始めましょう。読める文章が増えるほど、単語も覚えやすくなります。'], ['単語の意味が複数あって、どれを答えればいいか分かりません。', '中心のイメージを覚えておき、文脈で決めます。前後がよい内容か悪い内容か、だれのどんな場面かを確かめてから、候補を当てはめましょう。\nテストの選択肢では、単語の意味に合わないものを先に消すと、残りが少なくなって選びやすくなります。'], ['「をかし」と「あはれなり」は、どう訳し分けるの?', 'どちらも「趣がある」と訳せますが、感動の種類がちがいます。「をかし」は明るく知的な感動(おもしろい・美しい)、「あはれなり」はしみじみと心にしみる感動です。\n場面が明るいか、しんみりしているかで訳し分けると自然になります。']],
    terms: [['をかし', '趣がある・美しい・かわいらしい'], ['あはれなり', 'しみじみとした趣がある'], ['ありがたし', 'めったにない・すばらしい'], ['やがて', 'そのまま・すぐに'], ['いみじ', '程度がはなはだしい(よくも悪くも)'], ['つとめて', '早朝・翌朝'], ['音便', '発音しやすいように音が変わること(うつくしく → うつくしう)'], ['呼応の副詞', '決まった言葉とセットで意味が決まる副詞(え〜ず・な〜そ)']],
    miss: ['「をかし」を今の「おかしい(変だ)」で訳してしまう。今もある形の語ほど、古文の意味を確かめるくせをつける。', '「やがて」を「そのうちに」と訳す。「やがて=そのまま・すぐに」を、まちがった意味とセットで覚える。', '「いみじ」の訳を1つだけ覚えて、場面に合わない訳をつける。中心のイメージ(程度がすごい)から、場面に合わせて訳す。', '「え」「な」を見落とし、不可能や禁止の意味をぬかして訳す。文末に「ず」「そ」があったら、前に「え」「な」がないか探す。'],
    sum: ['今と意味がちがう単語(をかし・やがて・ありがたし など)から最優先で覚える。', '古文にしかない語(いと・つとめて・ゆかし など)も、よく出るものは確実に。', '形が変わった語は言い切りの形にもどす。「〜しう」は「〜しく」の音便。', '呼応の副詞は、え〜ず(不可能)、な〜そ(禁止)などをセットで覚える。', '意味が複数ある語は、中心のイメージをつかみ、文脈で1つに決める。'],
    next: '次は「古典文法(活用・助動詞)」の単元に進みましょう。単語の意味に加えて、助動詞(過去・推量・打消など)の働きが分かると、古文を一文ずつ正確に訳せるようになります。'
  };

  L.jx_std = {
    goal: '共通テスト・個別試験の土台となる古文単語・評論語・漢文句形の要点を整理し、問題文の中で意味を確定させる解き方を身につける。',
    intro: '国語の得点は、読解力だけでなく、【語の意味を知っているか】に大きく左右されます。古文単語・評論語・漢文の句形は、知っていれば一瞬で解ける問題が多く、知らなければどれだけ考えても解けません。この単元では、3つの分野の重要事項を総復習し、選択肢問題での使い方を練習します。',
    pre: 'この単元は、高校の「古文単語」「現代文(評論)」「漢文(句法)」の各単元の内容を、入試向けにまとめ直したものです。それぞれの基本を学んでから読むと、効果が大きくなります。\n古文単語について:古文には、今もある形なのに意味がちがう語(をかし・やがて など)と、今は使わない語(いと・つとめて など)があります。辞書や単語帳では、言い切りの形でのっています。\n評論語について:評論文(論理的な文章)には、「抽象」「普遍」「相対」など、ふだんの会話ではあまり使わない語が出てきます。意味が分かれば、文章の対立の構図が見えるようになります。\n漢文の句形について:漢文には、「使」「為〜所」「豈」のように、決まった読み方と訳し方をする字の組み合わせがあります。これを【句形(句法)】といいます。返り点(レ点・一二点)の読み方は、すでに分かっているものとして進めます。',
    secs: [
      { h: '語句問題の解き方:辞書的な意味で消す', t: '入試の語句問題(「傍線部の意味として最も適当なものを選べ」)は、次の型で解きます。\n①傍線の単語の【辞書的な意味】を思い出す。\n②その意味に合わない選択肢を消す。\n③残った選択肢を【文脈】で比べる。\nなぜこの順番なのでしょうか。文脈だけで選ぶと、「本文のあらすじには合うが、単語の意味とはずれている」選択肢(ひっかけ)を選んでしまうからです。入試の選択肢は、文脈に合いそうなものが複数用意されていることが多いのです。\n先に辞書的な意味で候補をしぼり、そのあとで文脈を使う。この順番を守るだけで、ひっかけに強くなります。',
        key: '語句問題は「辞書的な意味で消す → 残りを文脈で比べる」の順。文脈だけで選ばない。',
        ex: [{ q: '傍線部「ありがたき人」の意味として最も適当なものは?\nア 感謝すべき人 イ めったにいないほどすぐれた人 ウ 気の毒な人', hint: '「ありがたし」を「有り+難し」に分けて考えよう。', steps: ['「ありがたし」=有り+難し → 存在することが難しい → めったにない。', 'そこから「めったにないほどすばらしい」の意味も生まれる。', 'ア「感謝すべき」は現代語の意味なので消す。ウは意味と無関係なので消す。'], a: 'イ めったにいないほどすぐれた人', check: '「めったにない」という中心の意味が、イにだけふくまれていることを確かめる。' }] },
      { h: '古文単語:今と意味がちがう語を軸に', t: '入試の語句問題は、ほとんどが【現代語と意味がちがう語】から出ます。\nをかし(趣がある)、あはれなり(しみじみとした趣がある)、ありがたし(めったにない)、やがて(そのまま・すぐに)、おどろく(目を覚ます・気づく)、ののしる(大声で騒ぐ)、うつくし(かわいらしい)、なかなか(かえって)、年ごろ(長年)、あさまし(驚きあきれる)、ながむ(物思いにふけって見る)、すさまじ(興ざめだ)\nこれらは、【今の意味】が選択肢に入っていることが多いので、「今の意味の選択肢は、まず疑う」くらいの気持ちで見ます。\nまた、意味がいくつもある語(いみじ・あやし など)は、中心のイメージを覚えておき、文脈で訳を決めます。「いみじ」は「程度がふつうではない」、「あやし」は「ふつうとちがう」が中心です。',
        key: '選択肢にある「今の意味」は、まず疑う。多義語は中心のイメージで判断する。',
        ex: [{ q: '作例「夜ふけて、物の音におどろきぬ。」の「おどろき」の意味として最も適当なものは?\nア びっくりした イ 目を覚ました ウ 気味悪く思った', hint: '古文の「おどろく」の中心の意味は「はっとする」。夜ふけの場面だよ。', steps: ['古文の「おどろく」は、「はっと気づく」「目を覚ます」の意味。今の「びっくりする」とは少しずれる。', '場面は「夜がふけて」。寝ている時間帯に、何かの音がした。', '夜に音で「はっとする」のは、眠りから目を覚ますこと → イ。ア(今の意味)とウは辞書的な意味から外れる。'], a: 'イ 目を覚ました', check: '「夜ふけて、物の音に目を覚ました」と訳して、場面として自然か確かめる。' }] },
      { h: '評論語:対義語のセットで覚える', t: '評論語は、【対になる語とセット】で覚えると、文章の対立構造がつかみやすくなります。評論文の多くは、2つの考え方を対立させ、その一方を批判したり、両方を乗りこえたりする形で書かれているからです。\n【抽象 ⇔ 具体】…共通点を取り出したもの ⇔ 個々の形あるもの\n【主観 ⇔ 客観】…自分の見方 ⇔ だれにとっても同じ見方\n【普遍 ⇔ 特殊】…すべてに当てはまる ⇔ 一部にだけ当てはまる\n【絶対 ⇔ 相対】…ほかと比べなくても成り立つ ⇔ ほかとの関係で成り立つ\n【必然 ⇔ 偶然】…必ずそうなる ⇔ たまたまそうなる\n【演繹 ⇔ 帰納】…一般的な原理から個別の結論を導く ⇔ 個別の例から一般的な法則を導く\n傍線部の説明問題では、傍線の中の評論語を【やさしい言葉に言いかえた選択肢】が正解になることが多いです。',
        key: '評論語は対義語のセットで覚える。正解の選択肢は、評論語をやさしく言いかえたものが多い。',
        ex: [{ q: '「近代科学の見方を相対化する」の意味として最も適当なものは?\nア 近代科学の見方だけが正しいと考える\nイ 近代科学の見方を、数ある見方の一つとしてとらえ直す\nウ 近代科学の見方を、完全に否定する', hint: '「相対」の対義語は「絶対」。', steps: ['「相対」=ほかとの関係・比較の中で成り立つこと。対義語は「絶対」(ほかと比べなくても成り立つ)。', '「相対化する」=絶対だと思っていたものを、ほかと比べて「一つの見方」として見直すこと。', 'アは「絶対視」で反対の意味。ウは「否定」で言いすぎ(相対化は否定ではない)。'], a: 'イ', check: 'イの「数ある見方の一つ」が、「ほかとの比較の中でとらえる」という相対の意味の言いかえになっているか確かめる。' }] },
      { h: '漢文の句形1:否定・疑問・反語', t: '【否定】\n・不A(Aず)…Aしない\n・無A(Aなし)…Aがない\n・非A(Aにあらず)…Aではない\n・二重否定:無不A(Aせざるはなし)=Aしないものはない=すべてAする\n【疑問・反語】\n・何(なんぞ)、安(いづくんぞ)…どうして〜か\n・豈A哉(あにAんや)…どうしてAだろうか、いやAではない\n疑問と反語は、同じ字を使うことが多く、形だけでは区別しにくいことがあります。見分けのポイントは、①文末が「〜んや」となるのは反語が多い、②文脈で「答えを求めている(疑問)」のか「強く打ち消している(反語)」のかを考える、の2つです。\n反語を訳すときは、【「〜だろうか、いや〜ない」まで書く】のを忘れないようにします。',
        key: '反語は「どうして〜だろうか、いや〜ない」と、打ち消しまで訳す。',
        ex: [{ q: '『史記』の一節「燕雀安くんぞ鴻鵠の志を知らんや」を現代語訳しよう。(燕雀=ツバメやスズメなどの小さな鳥、鴻鵠=オオトリやハクチョウなどの大きな鳥)', hint: '「安くんぞ〜んや」は反語の形。', steps: ['「安くんぞ〜んや」=どうして〜だろうか、いや〜ない(反語)。', '「燕雀」は小さな鳥=小人物、「鴻鵠」は大きな鳥=大人物のたとえ。', '「知らんや」=知っているだろうか。反語なので「いや、知らない」まで訳す。'], a: 'ツバメやスズメのような小さな鳥に、どうしてオオトリやハクチョウのような大きな鳥の志が分かるだろうか、いや分かりはしない(小人物には大人物の大きな志は分からない)。', check: '訳の最後に「いや〜ない」という打ち消しが入っているかを確かめる。' }] },
      { h: '漢文の句形2:使役・受身', t: '【使役】…人に何かをさせる。\n・使AB(AをしてBせしむ)=AにBさせる。令・教・遣も同じ形。\n・「使」の次に人(A)、その次に動作(B)が来て、Bから「使」へ返って「しむ」と読みます。\n【受身】…何かをされる。\n・見A(Aる・らる)=Aされる\n・為A所B(AのBする所と為る)=AにBされる\n・Aの部分には、動作をする人(〜によって)が入ります。\n使役と受身は、どちらも「人と動作の関係」を表す句形です。まず【句形の字(使・令・見・為〜所)を見つけて丸で囲む】と、読み方と訳がすぐに決まります。\nなお「使」「為」は、ふつうの動詞(使う・為す)としても使われます。後ろに「人+動作」が続いていれば句形と考えます。',
        key: '使AB=AをしてBせしむ(AにBさせる)、為A所B=AのBする所と為る(AにBされる)。',
        ex: [{ q: '『論語』の一節「使 子路 問 津」(使は使役の字)を書き下し、意味を答えよう。(子路は人名、津は渡し場)', hint: '「使AB」の形に当てはめよう。', steps: ['句形の字を探す →「使」=使役。形は「使AB」=AをしてBせしむ。', 'A=子路、B=問津(津を問ふ)。', '当てはめる:子路をして津を問はしむ(「しむ」はひらがな)。', '意味は「AにBさせる」→ 子路に渡し場をたずねさせた。'], a: '子路をして津を問はしむ(子路に渡し場の場所をたずねさせた)', check: '訳に「させた」が入っていて、たずねる動作をするのが子路であることを確かめる。' },
          { q: '『史記』の一節「後るれば則ち人の制する所と為る」の「人の制する所と為る」を現代語訳しよう。', hint: '「AのBする所と為る」は受身の形。', steps: ['「AのBする所と為る」=AにBされる(受身)。', 'A=人、B=制する(おさえつける・支配する)。', '当てはめて「人に支配される」。前の「後るれば」(おくれをとると)とつなげて意味を確かめる。'], a: '人に支配される(おくれをとると、他人に支配されてしまう)', check: '同じ一節の前半「先んずれば即ち人を制し」(先にやれば人を支配できる)と対になっていることを確かめる。' }] },
      { h: '漢文の句形3:限定・比較・仮定', t: '【限定】…範囲をしぼる。\n・唯A(ただAのみ)=ただAだけ\n・文末の耳・已・爾(のみ)=〜だけだ\n【比較】…ほかと比べる。\n・A不如B(AはBに如かず)=AはBに及ばない\n例:百聞は一見に如かず(百回聞くことは、一回見ることに及ばない)\n・莫A於B(BよりAなるは莫し)=BよりAなものはない=Bが最もAだ\n【仮定】…もし〜ならば。\n・如・若(もし〜ば)\n・苟(いやしくも〜ば)=かりにも〜ならば\n句形は、【字を見たら読み方が決まる】ものなので、例文ごと声に出して覚えるのが効果的です。「百聞は一見に如かず」のように、今もことわざとして使われているものから覚えると、形と意味が結びつきやすくなります。',
        key: 'A不如B=AはBに及ばない、莫A於B=Bが最もA。比較の形は、どちらが上かを言いかえて確かめる。' }
    ],
    faq: [['古文単語・評論語・漢文句形、どれから覚えればいい?', '古文単語の重要語から始めるのがおすすめです。古文の問題は、単語が分からないと本文全体が読めないからです。\n評論語は現代文を読みながら少しずつ、漢文句形は数が限られているので、短期間でまとめて覚えると効率的です。'], ['疑問と反語は、どう見分けるの?', '文末の読み方と文脈で見分けます。「〜んや」と読むものは反語であることが多いです。\nまた、文脈上、筆者や話し手が「答えを知りたい」のか、「分かりきったことを強く打ち消したい」のかを考えます。強い主張の場面なら反語と考えてよいことが多いです。'], ['評論語は、漢字から意味を想像してもいいの?', '手がかりにはなりますが、それだけで決めるのは危険です。たとえば「敷衍」「止揚」のような語は、漢字から意味を想像しにくく、まちがえやすいです。\n定義を覚えたうえで、本文の中でどう使われているかを確かめましょう。']],
    terms: [['抽象', 'いくつかのものから共通点を取り出すこと'], ['普遍', 'いつでもどこでも当てはまること'], ['相対', 'ほかとの関係・比較の中で成り立つこと'], ['演繹', '一般的な原理から個別の結論を導くこと'], ['帰納', '個別の例から一般的な法則を導くこと'], ['反語', '疑問の形で強く打ち消す表現'], ['使役', '人に何かをさせること(使AB=AをしてBせしむ)'], ['受身', '何かをされること(為A所B=AのBする所と為る)']],
    miss: ['古文単語を現代語の意味で選んでしまう(ありがたし=感謝)。選択肢に今の意味があったら、まず疑ってかかる。', '評論語の対義語を取りちがえる(演繹と帰納の逆など)。「演繹=原理から個別へ、帰納=個別から法則へ」と矢印の向きで覚える。', '使役の「使」を、ふつうの動詞「つかう」として読んでしまう。後ろに「人+動作」があれば使役と考える。', '反語を疑問として訳し、「いや〜ない」を書き忘れる。「〜んや」を見たら、打ち消しまで書く。'],
    sum: ['語句問題は「辞書的な意味で選択肢を消す → 文脈で決める」。', '古文単語は、今と意味がちがう語を軸に覚え、今の意味の選択肢を疑う。', '評論語は対義語のセットで覚え、言いかえた選択肢を探す。', '漢文は句形の字に印をつけ、決まった読み方を当てはめる。', '使AB=AをしてBせしむ、為A所B=AのBする所と為る、豈〜哉=反語、A不如B=AはBに及ばない。'],
    next: '次は「難関レベル:国語」の単元に進みましょう。古典文法(助動詞の識別)や敬語の方向など、根拠をもって訳す力を身につけると、難関大の問題にも対応できます。'
  };

  L.hd_jpn = {
    goal: '古典文法(助動詞の意味と接続)・敬語の敬意の方向・評論の難語を、根拠を示しながら正確に判断できるようになる。',
    intro: '難関大の国語では、「なんとなく訳す」のではなく、【文法的な根拠】をもって訳すことが求められます。助動詞なら接続と文脈、敬語なら「だれからだれへ」、評論語なら正確な定義。どれも、判断の手順を決めておけば、初めて見る文章でも同じように解けます。',
    pre: '古文の動詞・助動詞などは、後ろにつく言葉によって形が変わります(活用)。その形には6つの種類があり、【未然形・連用形・終止形・連体形・已然形・命令形】と呼びます。\n例:四段活用の「書く」→ 書か(ず)/書き(たり)/書く。/書く(とき)/書け(ども)/書け。\n動詞の活用の種類は、四段・上一段・上二段・下一段・下二段・カ変・サ変・ナ変・ラ変の9種類です。サ変は「す・おはす」など、カ変は「来(く)」です。\n【接続】とは、助動詞が、前の語の何形につくかというきまりです。たとえば打消の「ず」は未然形につき、過去の「けり」は連用形につきます。同じ形の助動詞でも、接続がちがえば別の語だと分かります。\n敬語については、尊敬語・謙譲語・丁寧語の3種類と、「尊敬語は動作をする人を、謙譲語は動作を受ける人を高める」という基本を確認しておきましょう。古文の代表的な敬語は、尊敬語「給ふ・おはす・のたまふ」、謙譲語「奉る・申す・参る」、丁寧語「侍り・候ふ」です。',
    secs: [
      { h: '助動詞は「接続」で候補をしぼる', t: 'なぜ接続が大事なのでしょうか。古文には、【同じ形なのに意味がちがう助動詞】がいくつもあるからです。たとえば「なり」「ぬ」「る」などです。文脈だけで判断すると、どちらにも訳せてしまい、迷います。\nそこで、まず【前の語の活用形】を確かめて候補をしぼり、そのあとで文脈で意味を決める、という2段階で判断します。\n手順:\n①助動詞の直前の語を見つける。\n②その語の活用の種類と、何形かを決める(必要なら、その語を活用させてみる)。\n③接続のきまりに当てはめ、どの助動詞かを決める。\n④文脈に合わせて、その助動詞の意味(複数あれば1つ)を決める。\n前の語の形を正しく決めるには、動詞の活用表が頭に入っていることが前提です。特に、終止形と連体形の形がちがう動詞(二段活用・サ変・カ変・ナ変・ラ変)は、識別の手がかりになります。',
        key: 'まず前の語の活用形(接続)で候補をしぼり、そのあと文脈で意味を決める。' },
      { h: '「なり」の識別:断定か伝聞・推定か', t: '【なり】には、2種類の助動詞があります。\n①【断定の「なり」】…体言・連体形につく。意味は断定(〜である)・存在(〜にある)。\n②【伝聞・推定の「なり」】…終止形(ラ変型の語には連体形)につく。意味は伝聞(〜という・〜そうだ)・推定(〜ようだ。音を根拠にすることが多い)。\n見分け方:前の語が【体言か、連体形か】なら断定、【終止形】なら伝聞・推定。\nただし、四段活用の動詞などは終止形と連体形が同じ形(書く・書く)なので、接続だけでは決まりません。そのときは文脈を見ます。音や声を聞いて判断している場面なら推定、人から聞いた話なら伝聞です。\nほかに、形容動詞の活用語尾(静かなり)や、動詞「なる」の連用形(なり)もあるので、前の語とあわせて1語かどうかも確かめます。',
        key: '体言・連体形+なり=断定、終止形+なり=伝聞・推定。終止形と連体形が同じなら文脈で決める。',
        ex: [{ q: '『土佐日記』冒頭「男もすなる日記といふものを、女もしてみむとてするなり。」の2つの「なり」の意味を判別しよう。', hint: 'それぞれの「なり」の直前の語(す/する)が何形かを考えよう。', steps: ['1つ目「すなる」:前の「す」はサ変動詞の終止形。終止形につく「なり」→ 伝聞・推定。「男も書くという日記」。', '2つ目「するなり」:前の「する」はサ変動詞の連体形。連体形につく「なり」→ 断定。「〜するのである」。', '終止形と連体形の形がちがう動詞(す/する)なので、接続ではっきり区別できる。'], a: '「すなる」の「なり」=伝聞(〜という)、「するなり」の「なり」=断定(〜である)', check: '全体を「男も書くという日記というものを、女の私も書いてみようと思って書くのである」と訳し、意味が通るか確かめる。' }] },
      { h: '「ぬ」「ね」の識別:完了か打消か', t: '【ぬ】には、2つの可能性があります。\n①【完了の助動詞「ぬ」(終止形)】…連用形につく。〜た・〜てしまった。\n②【打消の助動詞「ず」の連体形「ぬ」】…未然形につく。〜ない。\n【ね】も同じように2つあります。\n①【完了「ぬ」の命令形「ね」】…連用形につく。〜てしまえ。\n②【打消「ず」の已然形「ね」】…未然形につく。〜ないので・〜ないけれど(こそ の結びにもなる)。\n見分け方は、前の語が【未然形なら打消、連用形なら完了】です。四段活用なら、未然形はア段(咲か)、連用形はイ段(咲き)なので、見分けやすくなります。\nまた、①文末で言い切っている「ぬ」は完了のことが多い(打消は文末ではふつう「ず」)、②名詞の前の「ぬ」(連体形)は打消のことが多い、という形の手がかりも使えます。',
        key: '未然形+ぬ・ね=打消「ず」、連用形+ぬ・ね=完了「ぬ」。四段なら ア段=未然、イ段=連用。',
        ex: [{ q: '作例「咲かぬ花」と「花咲きぬ」の「ぬ」の意味をそれぞれ答えよう。', hint: '「咲か」「咲き」が何形かを考えよう。', steps: ['「咲く」は四段活用。「咲か」はア段なので未然形、「咲き」はイ段なので連用形。', '「咲かぬ花」:未然形+ぬ → 打消「ず」の連体形。後ろに名詞「花」が続くことも連体形と合う →「咲かない花」。', '「花咲きぬ」:連用形+ぬ → 完了の「ぬ」。文末で言い切っていることとも合う →「花が咲いた」。'], a: '咲かぬ花=打消(咲かない花)、花咲きぬ=完了(花が咲いた)', check: '打消なら文末では「花咲かず」になるはずで、「花咲きぬ」が打消ではないことを確かめる。' }] },
      { h: 'る・らる/す・さす・しむ/り', t: '【る・らる】…未然形につく。「る」は四段・ナ変・ラ変の未然形、「らる」はそれ以外の未然形につく。\n意味は【自発・可能・受身・尊敬】。心の動きを表す語(思ふ・しのぶ・ながむ など)につけば自発のことが多く、平安時代の文では、可能の意味は打消をともなう形(〜れず)で使われることが多いです。\n【す・さす・しむ】…未然形につく。意味は【使役・尊敬】。下に尊敬語(給ふ など)が続けば尊敬のことが多く(「せ給ふ」「させ給ふ」は二重の尊敬で、最高敬語と呼ばれます)、単独で使われていれば使役です。\n【り】…サ変の未然形・四段の已然形につく(「サ未四已(さみしい)」と覚える)。意味は【完了・存続】(〜た・〜ている)。\n「り」は、前の語の最後がエ段の音(書け・せ)になることが目印です。「書けり」「せり」を見たら、「り」ではないかと考えます。',
        key: 'る・らる=自発・可能・受身・尊敬、す・さす・しむ=使役・尊敬、り=サ変未然・四段已然につく完了・存続。',
        ex: [{ q: '「書けり」の「り」の意味と、接続の根拠を答えよう。', hint: '「書け」は「書く」の何形だろう。', steps: ['「書く」は四段活用。「書け」は已然形(または命令形)の形。', '「り」はサ変の未然形・四段の已然形につく助動詞 → 接続が合う。', '意味は完了・存続。文脈がなければ「書いている(存続)」と訳すのが基本。'], a: '完了・存続の「り」(四段動詞「書く」の已然形についている)。「書いている・書いた」。', check: '「り」の前がエ段の音(け)になっていることを確かめる。' },
          { q: '作例「ふるさとのこと、しのばる。」と「ふるさとのこと、思ひ出でらる。」の「る」「らる」の意味を答えよう。', hint: '「しのぶ」「思ひ出づ」は、どちらも心の動きを表す語。', steps: ['「しのぶ」(なつかしく思う)は心の動きを表す語。四段活用の未然形「しのば」に「る」がついている。', '「思ひ出づ」は下二段活用で、未然形「思ひ出で」に「らる」がついている(四段・ナ変・ラ変以外なので「らる」)。', 'どちらも心の動きを表す語について、「自然と〜される」という意味 → 自発。'], a: 'どちらも自発(自然となつかしく思われる/自然と思い出される)', check: '「自然と」を補って訳し、受身(〜に思い出される)や尊敬では意味が通りにくいことを確かめる。' }] },
      { h: '敬語は「種類 → 敬意の方向 → 主語」', t: '手順:\n①その語が尊敬語・謙譲語・丁寧語のどれかを決める。\n②【だれからの敬意か】…地の文なら作者(語り手)から、会話文なら話し手から、手紙なら書き手から。\n③【だれへの敬意か】…尊敬語は動作をする人へ、謙譲語は動作を受ける人へ、丁寧語は聞き手(読み手)へ。\n④敬語の有無と種類から、省略された主語や目的語を決める。\nなぜ④ができるのでしょうか。古文では、身分の高い人の動作には尊敬語がつき、そうでない人の動作にはつかない、という使い分けがかなり厳密だからです。たとえば、登場人物が帝と家来の2人なら、尊敬語のついた動作は帝の動作だと考えられます。\nこのように、敬語は「訳すため」だけでなく、【主語を決めるための手がかり】としても使えます。',
        key: '敬語は「種類 → だれから → だれへ」の順で判断し、省略された主語を決める手がかりにする。' },
      { h: '二方面への敬語と、下二段の「給ふ」', t: '【二方面への敬語】…「謙譲語+尊敬語」の順で重なると、動作を受ける人と動作をする人の両方を高めます。\n作例:(地の文)「大納言、帝に御文を奉り給ふ。」\n奉る(謙譲語)→ 受け手の帝へ/給ふ(尊敬語)→ する人の大納言へ。どちらも作者からの敬意。\n【下二段の「給ふ」】…「給ふ」には、尊敬語(四段活用)のほかに、謙譲語(下二段活用)があります。下二段の「給ふ」は主に会話文や手紙で「思ひ給ふ」「見給ふ」など、話し手自身の動作について、へりくだる気持ちを表します(〜ております・〜させていただく)。\n見分け方:活用の形を見ます。四段なら「給は・給ひ・給ふ・給ふ・給へ・給へ」、下二段なら「給へ・給へ・(給ふ)・給ふる・給ふれ・○」です。「給へ」の直後に「ず」「て」などが来る(未然形・連用形の「給へ」)なら下二段の謙譲語、と判断できます。',
        key: '謙譲語+尊敬語=二方面への敬語。下二段「給ふ」は話し手自身の動作につく謙譲語。',
        ex: [{ q: '作例「(地の文)大納言、帝に御文を奉り給ふ。」の「奉り」「給ふ」は、それぞれだれからだれへの敬意?', hint: '謙譲語は動作を受ける人、尊敬語は動作をする人を高める。', steps: ['「奉る」=謙譲語(差し上げる)。謙譲語は動作を受ける人を高める → 手紙を受け取る帝へ。', '「給ふ」=尊敬語(お〜になる)。尊敬語は動作をする人を高める → 手紙を差し上げる大納言へ。', '地の文なので、敬意の出どころはどちらも作者。'], a: '奉り=作者から帝への敬意、給ふ=作者から大納言への敬意', check: '「大納言が帝にお手紙を差し上げなさる」と訳し、帝と大納言の両方が高められているか確かめる。' }] },
      { h: '評論の難語は「定義+言いかえ」', t: '難関大の評論では、次のような語が説明なしで使われます。定義と、やさしい言いかえをセットで覚えます。\n【捨象】…抽象するときに、共通しない性質を切り捨てること。(抽象と表裏の関係)\n【敷衍】…意味や趣旨を、おし広げてくわしく説明すること。\n【止揚(アウフヘーベン)】…対立する2つのものを、それぞれの良さを生かしながら、より高い次元でまとめること。\n【形而上 ⇔ 形而下】…形をもたない精神的・抽象的なもの ⇔ 形のある物質的なもの。\n【表象】…心に思い浮かべるイメージ。また、何かを表すしるし(象徴)。\n【アイロニー】…皮肉。表面と反対の意味をこめた言い方。\n傍線部説明では、まず傍線の中の難語を定義で言いかえ、そのうえで本文の具体的な内容と対応させます。',
        key: '難語は定義で言いかえ、本文の具体的な内容と対応させて説明する。',
        ex: [{ q: '「地図は、現実の土地から多くの情報を捨象することで、かえって役に立つものになる。」を分かりやすく言いかえよう。', hint: '「捨象」=共通しない・不要な性質を切り捨てること。', steps: ['「捨象」=共通しない・不要な性質を切り捨てること。', '地図の場合:建物の色や木の一本一本など、目的に関係のない細かい情報を切り捨てる。', '「かえって役に立つ」=情報を減らしたほうが、必要な情報(道や位置関係)が見やすくなる。'], a: '地図は、現実の土地のこまかな情報をあえて切り捨てることで、必要な情報が見やすくなり、かえって役に立つものになる。', check: '言いかえた文に「捨象」の定義(不要な性質を切り捨てる)と、本文の具体(地図)が両方入っているか確かめる。' }] }
    ],
    faq: [['助動詞の接続は、全部覚えないといけないの?', '識別問題によく出る助動詞(なり・ぬ・る・らる・す・さす・り など)の接続は、必ず覚えましょう。\nほかの助動詞も、「未然形につくもの(ず・む・る・す など)」「連用形につくもの(き・けり・つ・ぬ・たり など)」「終止形につくもの(べし・らむ・めり など)」とグループで覚えると整理しやすくなります。'], ['敬語の「だれからの敬意か」は、なぜ大事なの?', '同じ敬語でも、地の文なら作者、会話文なら話し手の気持ちを表すからです。会話文で敬語が使われていると、話し手と聞き手の身分の関係が分かります。\n入試では「だれからだれへの敬意か」がそのまま問われることも多く、主語の判定にも直結します。'], ['評論の難語は、どうやって覚えればいい?', '評論文を読んでいて出てきたときに、その文の中での使われ方といっしょに覚えるのが効果的です。\n定義を覚えたら、「たとえば地図の場合は…」のように、自分で具体例を1つ考えておくと、傍線部説明の問題で使えるようになります。']],
    terms: [['接続', '助動詞が前の語の何形につくか'], ['伝聞・推定の「なり」', '終止形(ラ変型は連体形)につき、〜という・〜ようだ と訳す'], ['完了の「ぬ」', '連用形につく。〜た・〜てしまった'], ['完了・存続の「り」', 'サ変の未然形・四段の已然形につく助動詞'], ['自発', '心の動きを表す語について、「自然と〜される」という意味'], ['二方面への敬語', '謙譲語+尊敬語で、動作を受ける人とする人の両方を高めること'], ['捨象', '抽象するとき、共通しない性質を切り捨てること'], ['止揚', '対立する2つを、より高い次元でまとめること']],
    miss: ['「なり」を、接続を確かめずに文脈だけで断定と訳してしまう。必ず直前の語の活用形を先に確かめる。', '「ぬ」を、前の語の形を見ずに完了と決めてしまう。未然形(ア段)なら打消、連用形(イ段)なら完了と、形で判断する。', '謙譲語の敬意の相手を、動作をする人にしてしまう。謙譲語は「動作を受ける人」へ、と毎回言葉にして確かめる。', '下二段の「給ふ」(謙譲)を尊敬語と取りちがえる。活用の形(給へ+ず・て)と、話し手自身の動作かどうかで判断する。', '評論の難語を、漢字の印象だけで意味を想像する。定義を覚え、本文の具体例と対応させる。'],
    sum: ['助動詞は、まず接続で候補をしぼり、次に文脈で意味を決める。', '「なり」は終止形接続=伝聞・推定、体言・連体形接続=断定。', '「ぬ・ね」は未然形接続=打消「ず」、連用形接続=完了「ぬ」。', '「り」はサ変の未然形・四段の已然形(さみしい)につく。る・らる は自発・可能・受身・尊敬。', '敬語は「種類 → だれから → だれへ」の順で判断し、主語の決定に使う。', '評論の難語は、定義とやさしい言いかえをセットで覚える。'],
    next: '次は、実際の入試の古文・評論文を使った演習に進みましょう。ここで学んだ識別と敬語の手順を、長い本文の中でくり返し使うことで、初めて見る文章でも根拠をもって読めるようになります。'
  };
})(WPS.LESSONS);
